package com.lexia.legalassistant.data.repository

/**
 * Registro oficial estatutario de los 429 Artículos del Código Penal Federal (CPF).
 * Publicado en el Diario Oficial de la Federación, con el marco normativo penal sustantivo mexicano vigente.
 */
object CpfStatutoryData {

    data class ArticleMeta(
        val title: String,
        val category: String,
        val summary: String
    )

    val articles: Map<Int, ArticleMeta> = mapOf(
        1 to ArticleMeta("Ámbito Espacial de Validez del Código Penal", "Ámbito de Validez", "Este Código se aplicará en toda la República Mexicana para los delitos del orden federal y aquellos que inicien, preparen o consuman en territorio nacional con efectos en el exterior."),
        2 to ArticleMeta("Validez Penal en el Extranjero por Delitos Federales", "Ámbito de Validez", "Se aplicará por los delitos cometidos en el extranjero por mexicanos o contra mexicanos, si el reo se encuentra en el país, no ha sido juzgado definitivamente y el hecho es punible en ambos Estados."),
        3 to ArticleMeta("Delitos Continuados y Permanentes en el Extranjero", "Ámbito de Validez", "Los delitos continuados y permanentes cometidos en el extranjero que se sigan cometiendo en territorio nacional se perseguirán con arreglo a las leyes penales mexicanas."),
        4 to ArticleMeta("Validez Penal en Embajadas y Consulados", "Ámbito de Validez", "Los delitos cometidos en el extranjero por funcionarios diplomáticos o consulares mexicanos en ejercicio de sus funciones se juzgarán conforme a las leyes federales de México."),
        5 to ArticleMeta("Delitos en Buques y Aeronaves Nacionales", "Ámbito de Validez", "Se consideran cometidos en territorio nacional los delitos ejecutados a bordo de buques de guerra o mercantes y aeronaves nacionales en alta mar o espacio aéreo neutral."),
        6 to ArticleMeta("Principio de Especialidad y Tratados Internacionales", "Teoría del Delito", "Cuando se cometa un delito no previsto en este Código pero sí en una ley especial o en un tratado internacional ratificado por México, se aplicarán éstos observando las disposiciones de este Código."),
        7 to ArticleMeta("Concepto Dogmático de Delito: Acción y Omisión", "Teoría del Delito", "Delito es el acto u omisión que sancionan las leyes penales. En los delitos de resultado material también será atribuible el resultado típico a quien omita impedirlo teniendo el deber jurídico de evitarlo."),
        8 to ArticleMeta("Formas de Culpabilidad: Dolo y Culpa", "Teoría del Delito", "Las acciones u omisiones delictivas solamente pueden realizarse dolosa o culposamente. Queda proscrita toda forma de responsabilidad objetiva en el orden penal federal."),
        9 to ArticleMeta("Definición Legal del Dolo y la Culpa", "Teoría del Delito", "Obra dolosamente el que conociendo los elementos del tipo penal quiere o acepta su realización. Obra culposamente el que produce el resultado que no previó siendo previsible o previó confiando en que no se produciría."),
        10 to ArticleMeta("Principio de Inexcusabilidad de la Ley Penal", "Teoría del Delito", "La ignorancia de la ley penal no exime de su cumplimiento, pero los jueces podrán atenuar la pena cuando por la extrema ignorancia o marginación del infractor se aprecie falta de comprensión."),
        11 to ArticleMeta("Responsabilidad Penal de las Personas Morales", "Teoría del Delito", "Cuando un miembro o representante de una persona moral cometa un delito con los medios que ésta le proporcione de modo que resulte cometido a su nombre o beneficio, se impondrán sanciones a la entidad."),
        12 to ArticleMeta("Tentativa Punible Acabada e Inacabada", "Teoría del Delito", "Existe tentativa punible cuando mediante actos u omisiones idóneos e inequívocos se encamina directamente a la consumación de un delito, si ésta no se consuma por causas ajenas a la voluntad del agente."),
        13 to ArticleMeta("Formas de Autoría y Participación Criminal", "Teoría del Delito", "Son responsables del delito: los que acuerden o preparen su realización (I); los que lo realicen por sí (II); los que lo realicen conjuntamente (III); los que se sirvan de otro (IV); los que determinen dolosamente a otro (V); y los que presten auxilio (VI)."),
        14 to ArticleMeta("Graduación Punitiva de Cómplices e Instigadores", "Teoría del Delito", "A los cómplices e instigadores se les impondrán las penas previstas para el delito consumado con la atenuación correspondiente a su grado de intervención conforme a las reglas de individualización."),
        15 to ArticleMeta("Causas de Exclusión del Delito y Justificación", "Exclusión del Delito", "El delito se excluye cuando: concurra atipicidad; legítima defensa de la persona, bienes o derechos frente a agresión real, actual o inminente sin provocación; estado de necesidad; cumplimiento de un deber; o consentimiento válidamente otorgado."),
        16 to ArticleMeta("Error de Tipo y Error de Prohibición", "Exclusión del Delito", "El error invencible sobre los elementos del tipo o sobre la licitud de la conducta excluye la responsabilidad penal. Si el error fuere vencible, se sancionará como delito culposo si tiene prevista tal punibilidad."),
        17 to ArticleMeta("Exceso en las Causas de Justificación", "Exclusión del Delito", "El que se exceda en los límites de la legítima defensa o del estado de necesidad será sancionado con las penas fijadas para los delitos culposos."),
        18 to ArticleMeta("Presunción de Dolo y Prueba Ministerial", "Teoría del Delito", "La carga de la prueba de la culpabilidad y del dolo penal recae invariablemente en el Ministerio Público de la Federación conforme al principio de presunción de inocencia."),
        19 to ArticleMeta("Acreditación del Hecho Típico Antijurídico", "Teoría del Delito", "Para dictar sentencia condenatoria es indispensable comprobar fehacientemente la existencia del hecho típico atribuido y la plena culpabilidad del sentenciado."),
        20 to ArticleMeta("Circunstancias Calificativas: Premeditación y Alevosía", "Circunstancias Calificativas", "Hay premeditación cuando el reo causa deliberadamente el daño después de haber reflexionado sobre el delito. Hay alevosía cuando se sorprende intencionalmente a alguien de improviso impidiéndole defenderse."),
        21 to ArticleMeta("Circunstancias de Ventaja y Traición", "Circunstancias Calificativas", "Hay ventaja cuando el delincuente no corre riesgo alguno de ser muerto o lesionado por el ofendido. Hay traición cuando se quebranta la fe o seguridad que expresamente se había prometido a la víctima."),
        22 to ArticleMeta("Concurso Ideal y Real de Delitos", "Concurso de Delitos", "Hay concurso ideal cuando con una sola conducta se cometen varios delitos. Hay concurso real cuando con pluralidad de conductas independientes se cometen varios delitos."),
        23 to ArticleMeta("Reincidencia y Régimen de Habitualidad", "Reincidencia", "Hay reincidencia cuando el condenado por sentencia ejecutoria comete un nuevo delito antes de transcurrir los plazos legales de prescripción de la condena anterior."),
        24 to ArticleMeta("Catálogo General de Penas y Medidas de Seguridad", "Penas y Medidas", "Son penas y medidas de seguridad: prisión, tratamiento en libertad, semilibertad, trabajo a favor de la comunidad, sanción pecuniaria (multa y reparación del daño), decomiso, suspensión o privación de derechos e inhabilitación."),
        25 to ArticleMeta("Pena de Prisión y Régimen Penitenciario", "Penas y Medidas", "La prisión consiste en la privación de la libertad personal en los centros de reinserción social federales. Su duración se computará desde el momento de la detención material del procesado."),
        26 to ArticleMeta("Tratamiento en Libertad para Sancionados", "Penas y Medidas", "El tratamiento en libertad consiste en la aplicación de medidas laborales, educativas, de salud o curativas bajo la orientación y vigilancia de la autoridad ejecutora de penas."),
        27 to ArticleMeta("Semilibertad y Pernocta Institucional", "Penas y Medidas", "La semilibertad implica alternación de períodos de privación de la libertad con tratamiento en libertad, pudiendo cumplirse durante los fines de semana o con pernocta en el centro de reclusión."),
        28 to ArticleMeta("Trabajo en Favor de la Comunidad o de la Víctima", "Penas y Medidas", "El trabajo a favor de la comunidad consiste en la prestación de servicios no remunerados en instituciones públicas educativas, asistenciales o de salud durante jornadas no laborales."),
        29 to ArticleMeta("Sanción Pecuniaria: Multa y Reparación del Daño", "Penas y Medidas", "La sanción pecuniaria comprende la multa y la reparación del daño. La multa consiste en el pago de una cantidad líquida fijada en días multa tasados conforme a la UMA."),
        30 to ArticleMeta("Obligación Preferente de Reparación del Daño", "Penas y Medidas", "La reparación del daño tiene carácter de pena pública exigible de oficio por el Ministerio Público, gozando de preferencia absoluta de cobro frente a cualquier otra multa estatal."),
        31 to ArticleMeta("Alcance Integral de la Reparación del Daño", "Penas y Medidas", "La reparación comprende: I. Restitución de la cosa obtenida por el delito; II. Indemnización del daño material y moral; III. Resarcimiento de perjuicios; IV. Pago de tratamientos médicos y psicológicos de la víctima."),
        32 to ArticleMeta("Responsabilidad Solidaria en la Reparación", "Penas y Medidas", "Están obligados a reparar el daño solidariamente: los tutores, los dueños de empresas por actos de sus dependientes, las personas morales por sus directivos y el Estado por sus servidores públicos."),
        33 to ArticleMeta("Fijación Judicial del Monto de la Reparación", "Penas y Medidas", "El monto de la reparación del daño se fijará por los jueces con base en las pruebas fehacientes rendidas en el proceso, o conforme a la Ley Federal del Trabajo en caso de muerte."),
        34 to ArticleMeta("Destino del Fondo Auxiliar para la Reparación", "Penas y Medidas", "Los importes cobrados por multas y decomisos se destinarán al Fondo de Ayuda, Asistencia y Reparación Integral a Víctimas conforme a la Ley General de Víctimas."),
        35 to ArticleMeta("Conversión de Multa por Trabajo Comunitario", "Penas y Medidas", "Cuando el sentenciado no pueda cubrir la multa por insolvencia económica comprobada, el juez podrá permutarla por jornadas de trabajo en beneficio de la comunidad."),
        36 to ArticleMeta("Distribución Proporcional de la Reparación", "Penas y Medidas", "Si los bienes del reo fueren insuficientes para cubrir todas las responsabilidades, se pagará prioritariamente la reparación a la víctima y en segundo término las multas al fisco."),
        37 to ArticleMeta("Carácter Imprescriptible de la Reparación de Delitos Graves", "Penas y Medidas", "La obligación de reparar el daño derivado de delitos graves y violaciones a derechos humanos no prescribirá mientras subsista el daño material o psicológico en la víctima."),
        38 to ArticleMeta("Exigibilidad Coactiva de la Reparación del Daño", "Penas y Medidas", "La reparación del daño no cubierta voluntariamente se exigirá mediante el procedimiento coactivo de ejecución fiscal trabando embargo sobre los bienes del condenado."),
        39 to ArticleMeta("Cómputo Judicial del Día Multa", "Penas y Medidas", "El día multa equivale a la percepción neta diaria del sentenciado en el momento de consumar el delito, no pudiendo ser inferior al salario mínimo ni exceder de quinientos tantos."),
        40 to ArticleMeta("Decomiso de Instrumentos, Objetos y Productos del Delito", "Penas y Medidas", "Los instrumentos con que se cometió el delito, así como las cosas que sean objeto o producto de él, se decomisarán si son de uso ilícito o pasarán a propiedad del Estado."),
        41 to ArticleMeta("Destrucción de Armas y Sustancias Prohibidas", "Penas y Medidas", "Las armas, narcóticos, explosivos y objetos peligrosos decomisados serán destruidos de inmediato por la autoridad judicial o entregados a las fuerzas armadas para su custodia."),
        42 to ArticleMeta("Suspensión de Derechos Políticos y Civiles", "Penas y Medidas", "La pena de prisión impone forzosamente la suspensión de los derechos políticos de votar y ser votado, así como de los derechos de tutela, curatela y apoderado durante la condena."),
        43 to ArticleMeta("Inhabilitación y Destitución para Empleo Público", "Penas y Medidas", "La inhabilitación impuesta a servidores públicos priva definitivamente del empleo, cargo o comisión que desempeñaban e impide obtener otro empleo público por el término fijado."),
        44 to ArticleMeta("Pérdida de la Patria Potestad y Derechos de Familia", "Penas y Medidas", "En los delitos cometidos contra los hijos, pupilos o cónyuge, el juez podrá decretar la pérdida de la patria potestad, guarda, custodia o derecho hereditario."),
        45 to ArticleMeta("Publicación Especial de Sentencia Condenatoria", "Penas y Medidas", "La publicación de sentencia consiste en la inserción de la parte resolutiva en uno o dos periódicos de mayor circulación a costa del delincuente como reparación moral."),
        46 to ArticleMeta("Amonestación Pública y Advertencia Judicial", "Penas y Medidas", "La amonestación consiste en la advertencia pública o privada que el juzgador hace al sentenciado sobre las consecuencias de la reincidencia estimulándolo a la enmienda."),
        47 to ArticleMeta("Caución de No Ofender y Medidas de Protección", "Penas y Medidas", "La caución de no ofender consiste en la garantía que el reo debe otorgar de que no causará daño a la víctima o testigos, bajo apercibimiento de arresto inmediato."),
        48 to ArticleMeta("Prohibición de Ir a Determinado Lugar o Residir en Él", "Penas y Medidas", "El juez podrá prohibir al sentenciado acercarse a determinados lugares, domicilios o zonas donde habite o labore la víctima o sus familiares directos."),
        49 to ArticleMeta("Vigilancia de la Autoridad sobre Sentenciados", "Penas y Medidas", "La vigilancia de la autoridad tiene por objeto orientar y supervisar la conducta del sentenciado en libertad para procurar su reinserción y prevenir la reincidencia."),
        50 to ArticleMeta("Tratamiento Psiquiátrico para Inimputables", "Penas y Medidas", "A los inimputables que cometan un hecho típico se les aplicará tratamiento médico o psiquiátrico en internamiento o en libertad para salvaguarda de su salud y la sociedad."),
        51 to ArticleMeta("Criterios de Individualización Judicial de las Penas", "Individualización de Penas", "Para individualizar las penas el juez tomará en cuenta la gravedad del hecho típico, el grado de culpabilidad, la naturaleza de la acción, la magnitud del daño y motivos determinantes."),
        52 to ArticleMeta("Circunstancias Personales y Sociales del Infractor", "Individualización de Penas", "El juzgador apreciará la edad, educación, ilustración, costumbres, condiciones socioeconómicas del sujeto y su conducta precedente para graduar la sanción aplicable."),
        53 to ArticleMeta("Atenuación por Inmadurez o Vulnerabilidad", "Individualización de Penas", "Cuando el autor haya delinquido impulsado por extrema miseria o falta de instrucción, el juzgador podrá fijar una pena inferior al mínimo legalmente establecido."),
        54 to ArticleMeta("Aumento de Pena por Calificativas Especiales", "Individualización de Penas", "Cuando concurran calificativas de alevosía, traición, ventaja premeditada o parentesco, la pena de prisión podrá aumentarse hasta en una mitad sobre el límite superior."),
        55 to ArticleMeta("Punición del Concurso Ideal de Delitos", "Concurso de Delitos", "En caso de concurso ideal de delitos se aplicará la pena correspondiente al delito que merezca la mayor, la cual podrá aumentarse hasta en una mitad del máximo del delito mayor."),
        56 to ArticleMeta("Punición del Concurso Real de Delitos", "Concurso de Delitos", "En caso de concurso real de delitos se acumularán las penas de los distintos delitos cometidos, sin que la suma total pueda exceder de sesenta años de prisión."),
        57 to ArticleMeta("Graduación de Penas en Tentativa", "Individualización de Penas", "A los autores de tentativa se les aplicará hasta las dos terceras partes de la pena que correspondería al delito consumado, atendiendo al grado de ejecución alcanzado."),
        58 to ArticleMeta("Punición en Delitos Culposos", "Individualización de Penas", "Los delitos culposos se sancionarán con hasta una cuarta parte de las penas asignadas al delito doloso, salvo los casos agravados por conducción bajo influjo de tóxicos."),
        59 to ArticleMeta("Punición de Cómplices Secundarios", "Individualización de Penas", "A los partícipes que auxilien al autor sin acuerdo previo se les aplicará hasta la mitad de la pena prevista para los autores directos del ilícito consumado."),
        60 to ArticleMeta("Suspensión o Pérdida de Derechos Profesionales", "Penas y Medidas", "Los profesionistas sentenciados por delitos cometidos en el ejercicio de su profesión o técnica podrán ser inhabilitados de uno a cinco años para ejercerla."),
        61 to ArticleMeta("Tratamiento a Sujetos con Trastorno Mental Superveniente", "Penas y Medidas", "Si el sentenciado cae en trastorno mental durante el cumplimiento de la condena de prisión, será trasladado a un establecimiento psiquiátrico computándose el tiempo."),
        62 to ArticleMeta("Sanción Penal a Extranjeros y Expulsión", "Penas y Medidas", "A los extranjeros sentenciados a penas de prisión se les podrá conmutar la pena por la expulsión definitiva del territorio nacional conforme a los tratados internacionales."),
        63 to ArticleMeta("Pena de Prisión en Delitos Continuados", "Individualización de Penas", "En el delito continuado se aumentará la pena de prisión hasta en una mitad de la que corresponda al delito simple consumado con unidad de propósito delictivo."),
        64 to ArticleMeta("Reglas de Sustitución y Conmutación de Sanciones", "Sustitución de Penas", "El juez podrá sustituir la prisión que no exceda de tres años por trabajo en favor de la comunidad o tratamiento en libertad, siempre que el reo no sea reincidente."),
        65 to ArticleMeta("Condiciones para la Conmutación de la Pena", "Sustitución de Penas", "La conmutación o sustitución sólo surtirá efectos si el sentenciado ha reparado íntegramente el daño causado a la víctima y cubierto la fianza que garantice su conducta."),
        66 to ArticleMeta("Revocación de Beneficios de Sustitución Punitiva", "Sustitución de Penas", "Si el sentenciado incumple las medidas de tratamiento o comete un nuevo delito doloso, se revocará la sustitución debiendo compurgar la pena de prisión pendiente."),
        67 to ArticleMeta("Cómputo de la Prisión Preventiva Sufrida", "Penas y Medidas", "El tiempo de prisión preventiva o arraigo sufrido por el imputado durante el proceso penal se abonará íntegramente a la pena de prisión que se le imponga en la sentencia."),
        68 to ArticleMeta("Prisión Domiciliaria a Mayores de 70 Años", "Penas y Medidas", "Los jueces podrán ordenar que la prisión se compurgue en el domicilio del sentenciado cuando éste tenga más de 70 años o padezca enfermedad grave terminal."),
        69 to ArticleMeta("Régimen de Libertad Condicional Preparatoria", "Ejecución Penal", "La concesión de la libertad preparatoria o condicional se regirá por la Ley Nacional de Ejecución Penal garantizando la reparación del daño a las víctimas."),
        70 to ArticleMeta("Sustitución de Multa por Jornadas de Trabajo", "Penas y Medidas", "Cada jornada de trabajo en favor de la comunidad saldará dos días multa cuando el sentenciado acredite insolvencia material para cubrir la sanción económica."),
        71 to ArticleMeta("Límite Temporal Máximo de la Prisión Federal", "Penas y Medidas", "En ningún caso la pena privativa de libertad impuesta por concurso de delitos en el fuero federal podrá ser superior a sesenta años de prisión."),
        72 to ArticleMeta("Decomiso de Ganancias Ilícitas Financieras", "Penas y Medidas", "Los rendimientos, intereses y ganancias financieras generadas por bienes objeto de decomiso penal pasarán automáticamente a propiedad del erario federal."),
        73 to ArticleMeta("Destino de Bienes Abandonados en Procedimiento", "Penas y Medidas", "Los bienes asegurados que no fueren reclamados por sus legítimos propietarios en el plazo de noventa días causarán abandono a favor de la Federación."),
        74 to ArticleMeta("Responsabilidad Administrativa Institucional", "Personas Morales", "Las personas jurídicas colectivas podrán ser sancionadas con clausura, disolución, suspensión de actividades o intervención judicial cuando sean usadas para delinquir."),
        75 to ArticleMeta("Sanción Pecuniaria a Entidades Colectivas", "Personas Morales", "A las personas morales responsables se les impondrán multas tasadas en días de ingresos netos independientes de las penas aplicables a las personas físicas partícipes."),
        76 to ArticleMeta("Criterios de Aplicación a Entidades Morales", "Personas Morales", "Para sancionar a personas morales se evaluará el grado de control preventivo interno (compliance penal), la jerarquía del infractor y el beneficio patrimonial obtenido."),
        77 to ArticleMeta("Causas Generales de Extinción Penal", "Extinción Penal", "La responsabilidad penal se extingue por: cumplimiento de la pena (78); muerte del delincuente (79); amnistía (80); perdón del ofendido (81); reconocimiento de inocencia (82); indulto (83); y prescripción (105)."),
        78 to ArticleMeta("Extinción por Cumplimiento de la Condena", "Extinción Penal", "El cumplimiento íntegro de la pena de prisión, pago de multas o compurgación de medidas extingue definitivamente la pretensión punitiva y el régimen de ejecución penal."),
        79 to ArticleMeta("Efectos de la Muerte del Delincuente", "Extinción Penal", "La muerte del imputado o sentenciado extingue la acción penal y las sanciones impuestas, a excepción del decomiso de instrumentos ilícitos y la reparación del daño exigible a la masa hereditaria."),
        80 to ArticleMeta("Extinción por Ley de Amnistía del Congreso", "Extinción Penal", "La amnistía extingue la acción penal y las sanciones impuestas por delitos políticos o concurrentes en los términos decretados por el Congreso de la Unión."),
        81 to ArticleMeta("Efectos del Perdón de la Víctima u Ofendido", "Extinción Penal", "El perdón de la víctima extingue la acción penal en delitos de querella necesaria, siempre que se otorgue de manera expresa y libre antes de dictarse sentencia irrevocable."),
        82 to ArticleMeta("Reconocimiento de Inocencia del Sentenciado", "Extinción Penal", "El reconocimiento de inocencia del sentenciado extingue la condena cuando se demuestre con pruebas supervenientes que el reo no cometió el delito o que el hecho no existió."),
        83 to ArticleMeta("Efectos del Indulto Otorgado por el Ejecutivo", "Extinción Penal", "El indulto extingue la potestad de ejecutar las penas impuestas en sentencia irrevocable, pero no extingue la obligación civil de reparar el daño a favor de la víctima."),
        84 to ArticleMeta("Indulto Necesario por Pruebas de Inocencia", "Extinción Penal", "Procederá el indulto necesario por acuerdo presidencial cuando aparezcan pruebas indubitables que acrediten que el sentenciado fue condenado por error judicial manifiesto."),
        85 to ArticleMeta("Indulto por Gracia del Presidente de la República", "Extinción Penal", "El indulto por gracia se otorgará por el Presidente de la República en casos excepcionales de salud precaria o aportación humanitaria relevante del condenado."),
        86 to ArticleMeta("Subsistencia de Decomisos ante el Indulto", "Extinción Penal", "El indulto no devolverá los instrumentos o efectos del delito que legalmente hayan sido decomisados por constituir sustancias o armas de posesión prohibida."),
        87 to ArticleMeta("Reglas de Concesión del Perdón de la Víctima", "Extinción Penal", "El perdón otorgado a uno de los coautores en delitos de querella necesaria favorecerá a todos los demás partícipes procesales."),
        88 to ArticleMeta("Perdón en Delitos Cometidos por Menores de Edad", "Extinción Penal", "Cuando el ofendido sea menor de edad o incapaz, el perdón sólo podrá otorgarlo quien ejerza la patria potestad o tutoría con la aprobación expresa del Ministerio Público."),
        89 to ArticleMeta("Inadmisibilidad de Perdón bajo Condición", "Extinción Penal", "El perdón no puede sujetarse a condición alguna y surtirá efectos irrevocables desde el momento en que se ratifique ante la presencia del juzgador penal."),
        90 to ArticleMeta("Subsistencia de Reparación ante Perdón Tácito", "Extinción Penal", "El perdón expreso o tácito respecto de la pretensión punitiva penal no impedirá la acción civil de cobro de daños y perjuicios pendientes."),
        91 to ArticleMeta("Fundamento y Efectos de la Prescripción Penal", "Prescripción", "La prescripción es personal y extingue la acción penal y las penas impuestas por el solo transcurso del tiempo fijado en la ley sin que se verifiquen actos de persecución."),
        92 to ArticleMeta("Examen Oficioso Obligatorio de la Prescripción", "Prescripción", "Los jueces y el Ministerio Público examinarán y declararán de oficio la prescripción penal en cualquier etapa del procedimiento por ser de orden público."),
        93 to ArticleMeta("Prescripción en Delitos Continuados y Permanentes", "Prescripción", "En los delitos continuados y permanentes el término de prescripción comenzará a correr a partir de que cese la última conducta consumativa del hecho delictuoso."),
        94 to ArticleMeta("Prescripción en Delitos de Tentativa", "Prescripción", "En los delitos de tentativa el plazo prescriptivo se computará desde el día en que se realizó el último acto de ejecución encaminado a la consumación."),
        95 to ArticleMeta("Prescripción en Delitos Instantáneos", "Prescripción", "En los delitos instantáneos el plazo de la prescripción de la acción penal correrá desde el momento preciso en que se consumó la conducta punible."),
        96 to ArticleMeta("Interrupción del Término de Prescripción", "Prescripción", "La prescripción de la acción penal se interrumpe por las actuaciones de investigación formal y diligencias ministeriales dirigidas a la persecución de los autores."),
        97 to ArticleMeta("Prescripción contra Reos Prófugos en el Extranjero", "Prescripción", "Si el reo se refugia en el extranjero el término de la prescripción se suspenderá hasta en tanto se tramita y resuelve la solicitud formal de extradición internacional."),
        98 to ArticleMeta("Prescripción de Delitos Perseguibles por Querella", "Prescripción", "Los delitos perseguibles por querella prescribirán en un año desde que la víctima tenga conocimiento del delito, o en tres años con independencia de su conocimiento."),
        99 to ArticleMeta("Prescripción de la Acción Penal en Delitos con Multa", "Prescripción", "Cuando el delito sólo esté sancionado con multa pecuniaria, la acción penal prescribirá en el término de un año contados desde su consumación."),
        100 to ArticleMeta("Prescripción de Delitos con Penas no Privativas", "Prescripción", "En delitos sancionados con destitución, inhabilitación o suspensión de derechos, la acción prescribirá en dos años si no concurre pena de prisión."),
        101 to ArticleMeta("Prescripción en Delitos con Pena Privativa Alternativa", "Prescripción", "Cuando la ley señale prisión alternativamente con otra sanción, la prescripción se regirá invariablemente por el término medio de la pena privativa de libertad."),
        102 to ArticleMeta("Prescripción en Delitos Cometidos por Servidores Públicos", "Prescripción", "En los delitos cometidos por servidores públicos en el ejercicio de sus funciones, los términos de prescripción de la acción penal se duplicarán."),
        103 to ArticleMeta("Imprescriptibilidad de Delitos de Lesa Humanidad", "Prescripción", "La acción penal y las sanciones respecto del genocidio, desaparición forzada, tortura y crímenes de guerra son constitucional e internacionalmente imprescriptibles."),
        104 to ArticleMeta("Prescripción en Delitos Sexuales contra Menores", "Prescripción", "Tratándose de abuso sexual, hostigamiento, violación y pederastia cometidos contra menores, la prescripción comenzará a correr a partir de que la víctima cumpla dieciocho años de edad."),
        105 to ArticleMeta("Cálculo del Término Medio Aritmético de la Pena", "Prescripción", "La acción penal prescribirá en un plazo igual al término medio aritmético de la pena de prisión que señale la ley para el delito, sin que en ningún caso pueda ser menor de tres años."),
        106 to ArticleMeta("Cómputo en Delitos Agravados o Calificados", "Prescripción", "Para computar la prescripción en delitos con circunstancias calificativas o agravantes, se tomarán en cuenta las penalidades mínimas y máximas de dichas modalidades."),
        107 to ArticleMeta("Prescripción en Concurso de Delitos", "Prescripción", "En caso de concurso de delitos, las acciones penales que de ellos emanen prescribirán por separado conforme al término que a cada delito corresponda."),
        108 to ArticleMeta("Prescripción de la Pena de Prisión Impuesta", "Prescripción de Penas", "La potestad de ejecutar la pena de prisión impuesta en sentencia irrevocable prescribirá en un tiempo igual al de la duración de la condena, sin que pueda ser menor de tres años."),
        109 to ArticleMeta("Prescripción de la Multa Impuesta en Sentencia", "Prescripción de Penas", "La pena de multa impuesta en sentencia firme prescribirá en el término de tres años contados a partir de que la resolución judicial cause ejecutoria formal."),
        110 to ArticleMeta("Prescripción de Penas no Privativas Firmes", "Prescripción de Penas", "Las penas consistentes en decomiso, trabajo en favor de la comunidad o amonestación prescribirán en dos años desde que cause ejecutoria la sentencia."),
        111 to ArticleMeta("Prescripción de la Reparación del Daño Judicial", "Prescripción de Penas", "La obligación de reparar el daño impuesta en sentencia ejecutoria prescribirá en el plazo de dos años contados desde que el acreedor pueda exigir su cobro."),
        112 to ArticleMeta("Interrupción de la Prescripción de la Condena", "Prescripción de Penas", "La prescripción de las penas privativas de libertad se interrumpe por la aprehensión del condenado o por requerimientos de la autoridad ejecutora."),
        113 to ArticleMeta("Evasión de Presos y Cómputo de la Prescripción", "Prescripción de Penas", "En caso de quebrantamiento de condena o fuga del sentenciado, el término de prescripción comenzará a correr nuevamente desde el día siguiente a la evasión."),
        114 to ArticleMeta("Prescripción contra Sentenciados Ausentes", "Prescripción de Penas", "El tiempo que el sentenciado permanezca fuera del territorio nacional no se computará para los efectos de la prescripción de la pena impuesta."),
        115 to ArticleMeta("Prescripción de Medidas de Seguridad Especiales", "Prescripción de Penas", "Las medidas de seguridad aplicables a personas inimputables prescribirán en el tiempo máximo señalado para la compurgación del tratamiento asignado."),
        116 to ArticleMeta("Efectos Extintivos Plenos de la Prescripción Declarada", "Prescripción", "Declarada firme la prescripción de la pena, se cancelarán de inmediato los antecedentes penales, registros cautelares y fichas sigilares del sentenciado."),
        117 to ArticleMeta("Responsabilidad por Retardo en Notificar la Prescripción", "Prescripción", "El funcionario judicial o ministerial que oculte o demore indebidamente la declaratoria de prescripción incurrirá en responsabilidad administrativa y penal."),
        118 to ArticleMeta("Normas Supletorias en Materia de Prescripción Penal", "Prescripción", "Las disposiciones sobre prescripción contenidas en las leyes especiales federales prevalecerán sobre este Código en cuanto a los tipos previstos en aquéllas."),
        119 to ArticleMeta("Delito de Traición a la Patria por Invasión Extranjera", "Seguridad Nacional", "Se impondrá pena de cinco a cuarenta años de prisión al mexicano que realice actos contra la independencia, soberanía o integridad de la Nación con la finalidad de someterla a potencia extranjera."),
        120 to ArticleMeta("Traición por Participación en Fuerzas Enemigas", "Seguridad Nacional", "Se sanciona al mexicano que tome las armas contra la patria bajo banderas de un ejército extranjero o colabore en operaciones bélicas contra tropas mexicanas."),
        121 to ArticleMeta("Traición por Entrega de Territorio o Armamento", "Seguridad Nacional", "Comete traición quien entregue a un gobierno extranjero plazas militares, naves de combate, pertrechos, secretos de defensa o recursos estratégicos nacionales."),
        122 to ArticleMeta("Traición por Conspiración con Potencia Foránea", "Seguridad Nacional", "Se castigará al mexicano que induzca o pacte con potencia extranjera la invasión armada de México o el bloqueo comercial que dañe la subsistencia nacional."),
        123 to ArticleMeta("Catálogo Taxativo del Delito de Traición a la Patria", "Seguridad Nacional", "Fracciones I a XV que tipifican el reclutamiento ilícito para ejército extranjero, financiamiento bélico contra México y revelación de secretos de seguridad."),
        124 to ArticleMeta("Sanciones a Extranjeros por Conspiración Beligerante", "Seguridad Nacional", "A los extranjeros que incurran en actos de traición a la patria en suelo mexicano se les aplicarán de cinco a treinta años de prisión y expulsión definitiva."),
        125 to ArticleMeta("Tentativa y Conspiración de Traición a la Patria", "Seguridad Nacional", "La conspiración para cometer traición a la patria se sancionará con prisión de dos a diez años aun cuando no llegue a iniciarse la ejecución material."),
        126 to ArticleMeta("Decomiso de Bienes en Traición a la Patria", "Seguridad Nacional", "La condena por traición a la patria traerá aparejada el decomiso de todos los bienes, empresas y derechos patrimoniales del sentenciado en favor del Estado."),
        127 to ArticleMeta("Tipo Penal de Espionaje contra la Seguridad Nacional", "Seguridad Nacional", "Se impondrá de cinco a veinte años de prisión a quien obtenga, sustraiga o entregue secretos de la defensa nacional a un gobierno o agente extranjero."),
        128 to ArticleMeta("Espionaje Tecnológico y Ciberespionaje Militar", "Seguridad Nacional", "Se sanciona a quien intercepte o hackee sistemas de comunicación, mando o inteligencia de las fuerzas armadas mexicanas para transferirlos al exterior."),
        129 to ArticleMeta("Agravantes de Espionaje Cometido por Militares", "Seguridad Nacional", "Las penas de espionaje se aumentarán hasta en una mitad cuando el agente activo sea miembro en activo de las fuerzas armadas o del servicio de inteligencia."),
        130 to ArticleMeta("Tipo Penal de Sedición contra Autoridades Federales", "Paz Pública", "Cometen sedición quienes de forma tumultuaria pero sin usar armas se resistan o ataquen a las autoridades de la Federación para impedir el libre ejercicio de sus funciones."),
        131 to ArticleMeta("Tipo Penal de Motín y Desorden Colectivo", "Paz Pública", "Cometen motín quienes para hacer uso de un derecho o pretextando su ejercicio se reúnan tumultuariamente y perturben el orden público con empleo de violencia."),
        132 to ArticleMeta("Tipo Penal de Rebelión Armada contra los Poderes", "Seguridad Nacional", "Cometen rebelión los que se alzan en armas contra los Poderes de la Unión para abolir o reformar la Constitución, despojar de funciones al Ejecutivo o disolver el Congreso."),
        133 to ArticleMeta("Sanciones a Mandos y Dirigentes de Rebelión", "Seguridad Nacional", "A los líderes, cabecillas y mandos superiores de un alzamiento de rebelión se les aplicará pena de diez a veinticinco años de prisión y multa económica."),
        134 to ArticleMeta("Sanciones a Tropas y Subalternos Rebeldes", "Seguridad Nacional", "A los subalternos o combatientes que depongan las armas voluntariamente ante el requerimiento de las fuerzas legítimas se les atenuará la pena hasta en dos tercios."),
        135 to ArticleMeta("Responsabilidad por Delitos Conexos en Rebelión", "Seguridad Nacional", "Los rebeldes responderán independientemente de los homicidios, saqueos, violaciones o robos cometidos durante las hostilidades al margen de los fines políticos."),
        136 to ArticleMeta("Prohibición de Amnistía por Delitos Comunes Conexos", "Seguridad Nacional", "Los beneficios de indulto o amnistía política para rebeldes no alcanzarán a quienes hayan cometido actos de tortura, secuestro o ejecuciones sumarias."),
        137 to ArticleMeta("Exención Punitiva por Retiro Oportuno de Rebelión", "Seguridad Nacional", "Quedará exento de pena quien habiendo conspirado para la rebelión se retire voluntariamente y denuncie el movimiento antes de que se inicien los actos bélicos."),
        138 to ArticleMeta("Conspiración para Rebelión y Sedición", "Seguridad Nacional", "La conspiración para consumar delitos de rebelión o sedición se sancionará con prisión de uno a cinco años y decomiso de fondos destinados al movimiento."),
        139 to ArticleMeta("Tipo Penal de Terrorismo con Sustancias Peligrosas", "Paz Pública", "Se impondrá pena de quince a cuarenta años de prisión a quien utilizando sustancias tóxicas, explosivos o armas de fuego realice actos que produzcan alarma, temor o terror en la población para atentar contra la seguridad nacional."),
        140 to ArticleMeta("Tipo Penal de Sabotaje a Instalaciones Estratégicas", "Paz Pública", "Se impondrá de diez a veinte años de prisión a quien con el fin de trastornar la vida económica del país dañe o destruya refinerías, presas, redes eléctricas o telecomunicaciones."),
        141 to ArticleMeta("Financiamiento al Terrorismo Nacional e Internacional", "Paz Pública", "Se castigará con quince a cuarenta años de prisión a quien recaude o aporte fondos económicos para ser utilizados en la comisión de actos terroristas."),
        142 to ArticleMeta("Encubrimiento y Refugio de Terroristas", "Paz Pública", "A quien oculte, proporcione refugio o facilite la fuga de personas vinculadas a grupos terroristas se le aplicarán de cinco a quince años de prisión."),
        143 to ArticleMeta("Uso Indebido de Armas Químicas y Bacteriológicas", "Paz Pública", "Se castigará con veinte a cuarenta años de prisión la fabricación, transporte o posesión de agentes biológicos, toxinas o armas químicas de destrucción masiva."),
        144 to ArticleMeta("Terrorismo Internacional y Ataques Transnacionales", "Derecho Internacional", "Sanciona con las máximas penas federales los actos terroristas cometidos en territorio extranjero contra intereses, instalaciones o ciudadanos mexicanos."),
        145 to ArticleMeta("Apología del Terrorismo y Propaganda Extremista", "Paz Pública", "A quien incite públicamente a la comisión de actos terroristas o haga apología de organizaciones terroristas se le impondrán de dos a seis años de prisión."),
        146 to ArticleMeta("Tipo Penal de Piratería Marítima y Aérea", "Derecho Internacional", "Cometen piratería los tripulantes de buques o aeronaves que por la fuerza material se apoderen de embarcaciones, tripulación o mercancías en aguas internacionales o espacio aéreo."),
        147 to ArticleMeta("Sanciones a Buques Piratas y Tripulantes", "Derecho Internacional", "A los corsarios y piratas se les impondrán de quince a treinta años de prisión y el decomiso de las embarcaciones y bienes capturados en favor del Estado."),
        148 to ArticleMeta("Violación de Inmunidad Diplomática Extranjera", "Derecho Internacional", "Se sanciona a quien viole los tratados de inmunidad cometiendo agresiones o privación de libertad contra embajadores, cónsules o representantes diplomáticos."),
        149 to ArticleMeta("Violación de la Neutralidad de la República", "Derecho Internacional", "A quien comprometa la paz de la República violando la neutralidad de México en conflictos armados internacionales se le aplicarán de cuatro a ocho años de prisión."),
        150 to ArticleMeta("Tipo Penal de Genocidio contra Grupos Humanos", "Derecho Internacional", "Comete genocidio quien con el propósito de destruir total o parcialmente a un grupo nacional, étnico, racial o religioso prive de la vida a sus miembros o someta a condiciones de destrucción (20 a 40 años)."),
        151 to ArticleMeta("Ataques a Vías Generales de Comunicación Federal", "Vías de Comunicación", "Se sanciona con prisión de uno a cinco años a quien destruya, dañe o interrumpa vías férreas, carreteras federales, puentes o navegación fluvial marítima."),
        152 to ArticleMeta("Interrupción Violenta del Transporte Federal", "Vías de Comunicación", "A quien detenga o bloquee por la fuerza el tránsito de trenes, vehículos de carga o autobuses en caminos federales se le aplicarán de dos a ocho años de prisión."),
        153 to ArticleMeta("Ataques a las Redes de Telecomunicación", "Vías de Comunicación", "Comete delito quien derribe o inutilice torres de transmisión, cables submarinos o infraestructura de telecomunicaciones estratégicas para el país."),
        154 to ArticleMeta("Avería y Desvío Peligroso de Aeronaves", "Vías de Comunicación", "Se castigará con diez a veinte años de prisión a quien introduzca explosivos o cause averías dolosas en aviones mercantes poniendo en riesgo el vuelo."),
        155 to ArticleMeta("Señales Falsas de Auxilio a la Navegación", "Vías de Comunicación", "Quien emita señales marítimas o aeronáuticas falsas provocando naufragio, choque o extravío de transportes sufrirá penas de cinco a doce años de prisión."),
        156 to ArticleMeta("Violación de Correspondencia Postal Privada", "Vías de Comunicación", "Se impondrá de seis meses a dos años de prisión a quien abra, intercepte o destruya indebidamente cartas o paquetes postales confiados al servicio público."),
        157 to ArticleMeta("Apertura Indebida por Empleados de Correos", "Vías de Comunicación", "Los empleados postales que sustraigan, abran o comercialicen correspondencia privada sufrirán el doble de la pena e inhabilitación definitiva del servicio."),
        158 to ArticleMeta("Intervención Ilegal de Llamadas Telefónicas", "Vías de Comunicación", "Se castigará con tres a doce años de prisión a quien intercepte comunicaciones telefónicas o digitales privadas sin orden judicial federal expresa."),
        159 to ArticleMeta("Comercialización de Equipos de Espionaje Telefónico", "Vías de Comunicación", "A quien fabrique, importe o venda dispositivos técnicos destinados a interceptar ilegalmente comunicaciones privadas se le aplicarán de dos a seis años."),
        160 to ArticleMeta("Posesión y Portación de Armas Prohibidas", "Seguridad Pública", "Se sanciona la posesión, fabricación o importación de puñales, navajas de muelle, boxer, artefactos explosivos caseros y armas reservadas por la Ley de Armas."),
        161 to ArticleMeta("Venta Ilícita de Armas a Menores", "Seguridad Pública", "Quien venda o entregue armas cortantes, de gas o de fuego a menores de edad incurrirá en pena agravada de tres a ocho años de prisión."),
        162 to ArticleMeta("Fabricación Clandestina de Explosivos Caseros", "Seguridad Pública", "Se sanciona a quien ensamble o transporte artefactos explosivos artesanales o bombas molotov sin autorización expresa de la SEDENA."),
        163 to ArticleMeta("Tráfico Clandestino de Material Bélico", "Seguridad Pública", "El ingreso ilegal de armas y pertrechos de guerra al territorio nacional se perseguirá como delito federal grave de seguridad nacional."),
        164 to ArticleMeta("Asociación Delictuosa y Pandillerismo", "Seguridad Pública", "Al que forme parte de una asociación o banda de tres o más personas con el propósito de delinquir se le impondrán de cuatro a ocho años de prisión."),
        165 to ArticleMeta("Agravantes para Jefes de Bandas Delictivas", "Seguridad Pública", "A los jefes, fundadores o dirigentes de asociaciones delictuosas se les aumentará la pena de prisión hasta en una mitad sin derecho a beneficios."),
        166 to ArticleMeta("Delincuencia Organizada Transnacional", "Seguridad Pública", "Las conductas de delincuencia organizada se regularán conforme a la Ley Federal contra la Delincuencia Organizada aplicándose supletoriamente este Código."),
        167 to ArticleMeta("Delito de Quebrantamiento de Sellos Oficiales", "Seguridad Pública", "Al que quebrante los sellos puestos por orden de la autoridad pública judicial o administrativa se le aplicarán de dos a siete años de prisión."),
        168 to ArticleMeta("Rotura de Sellos en Establecimientos Asegurados", "Seguridad Pública", "Si el quebrantamiento recae sobre inmuebles asegurados en procesos penales o de extinción de dominio, las penas privativas de libertad se duplicarán."),
        169 to ArticleMeta("Delito de Desobediencia a Mandato de Autoridad", "Seguridad Pública", "A quien rehúse prestar un servicio de interés público legalmente debido o desacate un requerimiento legítimo de autoridad se le impondrá multa y arresto."),
        170 to ArticleMeta("Tipo Penal de Oposición a Trabajos Públicos", "Seguridad Pública", "Al que con violencia material impida la ejecución de obras públicas legítimamente contratadas por el Gobierno Federal se le impondrán de dos a cinco años."),
        171 to ArticleMeta("Conducción de Vehículos en Estado de Ebriedad", "Seguridad Pública", "Se castigará con prisión de hasta tres años y suspensión de licencia a quien maneje vehículos de transporte federal bajo influjo de alcohol o drogas."),
        172 to ArticleMeta("Abandono de Personas Atropelladas por Conductores", "Seguridad Pública", "Al conductor que tras atropellar o lesionar a una persona se dé a la fuga sin prestarle auxilio médico se le aumentará la pena y cancelará la licencia."),
        173 to ArticleMeta("Tráfico Ilícito de Personas y Migrantes", "Seguridad Pública", "Se sanciona a quien albergue, transporte o interne ilegalmente a personas extranjeras en territorio nacional con fines de lucro económico."),
        174 to ArticleMeta("Extorsión a Personas Migrantes en Tránsito", "Seguridad Pública", "Se agravarán las penas hasta en una mitad cuando el tráfico de personas se acompañe de engaño, hacinamiento, violencia física o explotación laboral."),
        175 to ArticleMeta("Tráfico de Órganos y Células Humanas", "Salud Pública", "Se castigará con prisión de ocho a diecisiete años a quien trasplante, comercie o extraiga órganos humanos sin consentimiento legal informado."),
        176 to ArticleMeta("Comercio Clandestino de Tejidos Biológicos", "Salud Pública", "A quien promueva o intermedie la compraventa de sangre, tejidos o células madre humanas se le impondrá pena privativa de libertad de cuatro a diez años."),
        177 to ArticleMeta("Clonación Humana y Manipulación Genética Ilegal", "Salud Pública", "Se prohíbe y sanciona con seis a doce años de prisión la clonación reproductiva de seres humanos y la alteración dolosa del genoma humano."),
        178 to ArticleMeta("Resistencia de Particulares con Violencia", "Seguridad Pública", "Al que empleando violencia o amenazas se oponga a que la autoridad pública ejerza sus funciones legítimas se le aplicarán de uno a cuatro años."),
        179 to ArticleMeta("Amenazas contra Funcionarios Judiciales y Fiscales", "Seguridad Pública", "Si la resistencia o intimidación se dirige contra jueces, magistrados o agentes del Ministerio Público, la pena de prisión será de cuatro a ocho años."),
        180 to ArticleMeta("Coacción Ilícita sobre Servidores Públicos", "Seguridad Pública", "Al que coaccione a un servidor público para obligarlo a ejecutar o no ejecutar un acto de sus atribuciones se le impondrán de dos a seis años de prisión."),
        181 to ArticleMeta("Tentativa de Resistencia Armada contra Policías", "Seguridad Pública", "A quien esgrima armas de fuego contra elementos de la fuerza pública federal en cumplimiento del deber se le aplicarán penas autónomas de tentativa."),
        182 to ArticleMeta("Ultrajes a las Insignias y Símbolos Patrios", "Seguridad Pública", "Al que ultraje el Escudo, la Bandera o el Himno Nacional se le aplicará de seis meses a cuatro años de prisión y sanción económica federal."),
        183 to ArticleMeta("Uso Indebido de Uniformes y Condecoraciones", "Seguridad Pública", "Se castigará con uno a seis años de prisión a quien porte insignias, uniformes o divisas de las Fuerzas Armadas sin tener derecho oficial a ellos."),
        184 to ArticleMeta("Comercialización Clandestina de Uniformes Oficiales", "Seguridad Pública", "A quien fabrique, almacene o venda réplicas no autorizadas de uniformes militares o policiales se le aplicarán de tres a ocho años de prisión."),
        185 to ArticleMeta("Uso de Vehículos Balizados con Cromática Oficial", "Seguridad Pública", "Se sanciona a quien circule en vehículos particulares con torretas, estrobos o cromáticas idénticas a patrullas policiales o militares oficiales."),
        186 to ArticleMeta("Suministro Ilegal de Hidrocarburos Federales", "Seguridad Pública", "Se sanciona a quien sustraiga, resguarde o comercialice gasolina, diésel o petróleo crudo sin autorización de PEMEX conforme a la ley especial."),
        187 to ArticleMeta("Perforación Clandestina de Ductos Petroleros", "Seguridad Pública", "A quien perfore ductos o instale tomas clandestinas poniendo en riesgo a poblaciones urbanas se le impondrán de quince a veinticinco años de prisión."),
        188 to ArticleMeta("Transporte Ilegal de Petrolíferos sin Factura", "Seguridad Pública", "Comete delito quien transporte más de dos mil litros de combustible sin la factura o carta de porte fiscal que acredite su legítima adquisición."),
        189 to ArticleMeta("Adulteración y Alteración de Calidad de Combustibles", "Seguridad Pública", "A quien adultere combustibles mezclando solventes que dañen motores o el medio ambiente se le impondrán de cinco a diez años de prisión."),
        190 to ArticleMeta("Venta Ilícita de Gas LP en Pipas Clandestinas", "Seguridad Pública", "Se sanciona la distribución de gas licuado de petróleo en vehículos no registrados ante la Comisión Reguladora de Energía por riesgo colectivo."),
        191 to ArticleMeta("Daños a Plataformas Petroleras Marinas", "Seguridad Pública", "A quien cause sabotaje o daños a plataformas petroleras en la sonda de Campeche o aguas territoriales se le aplicarán de diez a veinte años."),
        192 to ArticleMeta("Robo de Energía Eléctrica en Alta Tensión", "Seguridad Pública", "Se sanciona la conexión clandestina a redes de transmisión de alta tensión de la CFE para uso industrial o comercial no registrado."),
        193 to ArticleMeta("Delito de Daño al Patrimonio Cultural Arqueológico", "Patrimonio Cultural", "A quien destruya, dañe o altere monumentos arqueológicos, históricos o artísticos nacionales se le aplicarán de tres a diez años de prisión."),
        194 to ArticleMeta("Tráfico Ilícito de Piezas Arqueológicas Prehispánicas", "Patrimonio Cultural", "Se castigará con cinco a doce años de prisión la exportación o venta de vestigios arqueológicos muebles propiedad originaria de la Nación."),
        195 to ArticleMeta("Saqueo y Excavación Clandestina de Yacimientos", "Patrimonio Cultural", "A quien realice excavaciones no autorizadas por el INAH en zonas de monumentos arqueológicos se le impondrá pena privativa de libertad de cuatro a diez años."),
        196 to ArticleMeta("Falsificación de Arte y Patrimonio Artístico", "Patrimonio Cultural", "Se sanciona la elaboración y venta de obras artísticas atribuidas dolosamente a grandes maestros de la pintura o escultura mexicana."),
        197 to ArticleMeta("Exportación Clandestina de Bienes Históricos", "Patrimonio Cultural", "Quien saque del país documentos históricos del Archivo General de la Nación incurrirá en delito contra la soberanía cultural mexicana."),
        198 to ArticleMeta("Destrucción de Archivos Públicos Históricos", "Patrimonio Cultural", "Los archivistas o servidores que destruyan expedientes con valor documental histórico sufrirán pena de cuatro a ocho años e inhabilitación."),
        199 to ArticleMeta("Protección Penal a Áreas Naturales Protegidas", "Medio Ambiente", "A quien tale, contamine o destruya flora o fauna en reservas de la biosfera o parques nacionales federales se le impondrán de dos a diez años."),
        200 to ArticleMeta("Tráfico Clandestino de Especies en Peligro de Extinción", "Medio Ambiente", "Se castigará con uno a nueve años de prisión a quien capture, acopie o comercie ejemplares de fauna o flora silvestre endémicas o amenazadas."),
        201 to ArticleMeta("Contaminación de Aguas y Acuíferos Federales", "Medio Ambiente", "A quien descargue sustancias tóxicas o desechos industriales en ríos, lagos o mantos acuíferos nacionales se le aplicarán de dos a diez años."),
        202 to ArticleMeta("Manejo Ilegal de Residuos Peligrosos Radiactivos", "Medio Ambiente", "Se castiga con cinco a quince años de prisión el almacenamiento no autorizado de materiales radiactivos o biológico-infecciosos peligrosos."),
        203 to ArticleMeta("Incendios Forestales Provocados en Bosques Federales", "Medio Ambiente", "A quien dolosamente provoque incendios forestales en terrenos boscosos de jurisdicción federal se le impondrán de cinco a doce años de prisión."),
        204 to ArticleMeta("Biopiratería de Recursos Genéticos Autóctonos", "Medio Ambiente", "Se sanciona la extracción y comercialización ilegal de variedades vegetales o principios activos autóctonos de comunidades indígenas."),
        205 to ArticleMeta("Delitos contra la Bioseguridad y Transgénicos", "Medio Ambiente", "A quien libere organismos genéticamente modificados en zonas protegidas sin autorización ambiental se le impondrán sanciones privativas."),
        206 to ArticleMeta("Pesca Ilegal en Zonas de Veda y Refugio Marino", "Medio Ambiente", "Se castiga con uno a cinco años de prisión la pesca ribereña o de altura en temporadas de veda decretadas por la autoridad pesquera federal."),
        207 to ArticleMeta("Caza Furtiva de Mamíferos Marinos Protegidos", "Medio Ambiente", "A quien cace ballenas, delfines o tortugas marinas se le impondrá pena privativa de libertad de dos a nueve años y decomiso de embarcaciones."),
        208 to ArticleMeta("Tráfico Ilegal de Maderas Preciosas Tropicales", "Medio Ambiente", "Se sanciona el transporte de cedro, caoba u otras maderas preciosas sin los sellos de aprovechamiento forestal sustentable de la SEMARNAT."),
        209 to ArticleMeta("Comercio de Carne y Huevos de Tortuga Marina", "Medio Ambiente", "A quien recolecte, posea o venda huevos de tortuga marina se le aplicará pena privativa de dos a nueve años de prisión sin derecho a sustitutivos."),
        210 to ArticleMeta("Reparación del Daño al Equilibrio Ecológico", "Medio Ambiente", "Las sentencias por delitos ambientales impondrán invariablemente la obligación de reparar integralmente el hábitat dañado restituyendo los ecosistemas."),
        211 to ArticleMeta("Agravantes Ambientales por Beneficio Comercial", "Medio Ambiente", "Las penas se aumentarán hasta en tres años más cuando los delitos contra el medio ambiente se cometan por corporaciones con fines de lucro masivo."),
        212 to ArticleMeta("Concepto de Servidor Público Federal para Efectos Penales", "Función Pública", "Es servidor público toda persona que desempeñe un empleo, cargo o comisión de cualquier naturaleza en la Administración Pública Federal, el PJF o el Congreso."),
        213 to ArticleMeta("Efectos de la Inhabilitación para la Función Pública", "Función Pública", "Los delitos cometidos por servidores públicos implicarán la destitución del puesto y la inhabilitación para desempeñar cargos públicos de uno a veinte años."),
        214 to ArticleMeta("Tipo Penal de Ejercicio Ilícito del Servicio Público", "Función Pública", "Comete este delito el servidor público que ejerza funciones sin tomar posesión legal, continúe ejerciéndolas indebidamente o custodie fondos sustraídos dolosamente."),
        215 to ArticleMeta("Tipo Penal de Abuso de Autoridad", "Función Pública", "Comete abuso de autoridad el servidor público que para impedir la ejecución de una ley se niegue a actuar, ordene detenciones arbitrarias o someta a vejaciones a particulares."),
        216 to ArticleMeta("Tipo Penal de Coalición de Servidores Públicos", "Función Pública", "Cometen coalición los servidores públicos que se coliguen para tomar medidas contrarias a una ley federal o para dimitir masivamente de sus puestos con el fin de impedir el servicio."),
        217 to ArticleMeta("Uso Ilícito de Atribuciones y Facultades", "Función Pública", "Se sanciona al servidor público que otorgue indebidamente concesiones, permisos, contratos de obra pública o deuda no autorizados por la legislación presupuestal."),
        218 to ArticleMeta("Tipo Penal de Concusión y Cobro Indebido", "Función Pública", "Comete concusión el servidor público que exija por sí o por interpósita persona dinero, valores o servicios a título de impuesto, contribución o dádiva indebida."),
        219 to ArticleMeta("Tipo Penal de Intimidación a Testigos o Denunciantes", "Función Pública", "Comete intimidación el servidor público que por sí o por terceros utilice violencia física o moral para evitar que alguien denuncie o rinda testimonio de un ilícito."),
        220 to ArticleMeta("Tipo Penal de Ejercicio Abusivo de Funciones", "Función Pública", "Se sanciona al servidor que otorgue contratos o beneficie con adquisiciones del Estado a cónyuges, parientes consanguíneos hasta el cuarto grado o socios mercantiles."),
        221 to ArticleMeta("Tipo Penal de Tráfico de Influencias", "Función Pública", "Comete este delito el servidor que promueva o gestione la tramitación o resolución ilícita de negocios públicos ajenos a sus facultades para obtener un lucro."),
        222 to ArticleMeta("Tipo Penal de Cohecho Activo y Pasivo (Soborno)", "Función Pública", "Comete cohecho el servidor público que solicite o reciba indebidamente dinero o dádivas; así como el particular que prometa u ofrezca dinero a un servidor para actuar u omitir."),
        223 to ArticleMeta("Tipo Penal de Peculado y Distracción de Fondos", "Función Pública", "Comete peculado el servidor público que para usos propios o ajenos distraiga de su objeto dinero, valores o bienes del Estado cuya custodia le haya sido confiada."),
        224 to ArticleMeta("Tipo Penal de Enriquecimiento Ilícito", "Función Pública", "Existe enriquecimiento ilícito cuando el servidor público no pueda acreditar el legítimo aumento de su patrimonio o la procedencia de los bienes a su nombre."),
        225 to ArticleMeta("Delitos contra la Administración de Justicia", "Función Pública", "Catálogo taxativo de fracciones aplicables a jueces, magistrados y agentes del Ministerio Público que retarden indebidamente, dicten resoluciones con dolo o fabriquen pruebas falsas."),
        226 to ArticleMeta("Sanciones a Secretarios y Actuarios Judiciales", "Función Pública", "A los funcionarios del PJF que asienten hechos falsos en diligencias judiciales se les impondrán de cuatro a diez años de prisión y destitución definitiva."),
        227 to ArticleMeta("Delitos en la Ejecución de Penas Privativas", "Función Pública", "Se sanciona a los directores de centros penitenciarios que otorguen libertades ilegales o permitan tratos inhumanos y tortura dentro de los penales."),
        228 to ArticleMeta("Responsabilidad Penal Médica y Técnica", "Ejercicio Profesional", "Los médicos, cirujanos y profesionistas responderán penalmente de los daños que causen a la salud o vida de sus pacientes por negligencia, impericia dolosa o abandono de enfermos."),
        229 to ArticleMeta("Suspensión en el Ejercicio de la Medicina", "Ejercicio Profesional", "Además de las penas privativas de libertad, se podrá imponer la suspensión de uno a cinco años en el ejercicio de la medicina a los profesionales condenados."),
        230 to ArticleMeta("Suministro de Medicamentos Nocivos o Vencidos", "Salud Pública", "Se sanciona al médico o farmacéutico que con conocimiento suministre medicamentos nocivos, alterados o vencidos provocando menoscabo en la salud."),
        231 to ArticleMeta("Delitos de Abogados, Patronos y Litigantes", "Ejercicio Profesional", "Cometen delito los abogados que aleguen hechos falsos a sabiendas, utilicen documentos apócrifos o abandonen la defensa de su cliente dejándolo indefenso."),
        232 to ArticleMeta("Patrocinio Infiel y Defensa Concurrente", "Ejercicio Profesional", "Se castigará al litigante que patrocine a dos partes con intereses contrarios en el mismo negocio o revele secretos de su defendido a la contraparte."),
        233 to ArticleMeta("Cobro Fraudulento de Honorarios Legales", "Ejercicio Profesional", "A los mandatarios judiciales que exijan pagos de costas inexistentes o se apropien de indemnizaciones cobradas a nombre de sus clientes se les impondrá pena de fraude."),
        234 to ArticleMeta("Falsificación de Moneda y Papel Moneda Federal", "Fe Pública", "Comete este delito quien produzca, almacene o introduzca al país billetes o monedas falsificados con denominación de curso legal en la República (5 a 12 años)."),
        235 to ArticleMeta("Circulación y Uso Doloso de Moneda Falsa", "Fe Pública", "Se sanciona a quien a sabiendas ponga en circulación monedas o billetes falsificados entregándolos como pago a particulares o instituciones."),
        236 to ArticleMeta("Falsificación de Moneda Extranjera en México", "Fe Pública", "Las mismas penas de cinco a doce años de prisión se aplicarán a quien falsifique billetes o monedas de curso legal en el extranjero dentro de México."),
        237 to ArticleMeta("Posesión de Matrices y Troqueles para Falsificar", "Fe Pública", "A quien posea troqueles, láminas de grabado, tintas especiales o papel moneda confidencial de Banxico se le aplicarán de cuatro a diez años."),
        238 to ArticleMeta("Alteración de Moneda Genuina y Devaluación Material", "Fe Pública", "Se sanciona a quien cercene o altere el metal de monedas de oro o plata genuinas disminuyendo dolosamente su peso intrínseco."),
        239 to ArticleMeta("Falsificación de Sellos Oficiales de la Federación", "Fe Pública", "Se castigará con cuatro a nueve años de prisión a quien falsifique el Gran Sello de la Nación, sellos judiciales o troqueles de aduanas federales."),
        240 to ArticleMeta("Uso Ilegal de Sellos Oficiales Auténticos", "Fe Pública", "A quien habiendo obtenido legalmente sellos o troqueles oficiales auténticos los estampe indebidamente en beneficio propio se le sancionará como falsificador."),
        241 to ArticleMeta("Falsificación de Marcas Comerciales y Patentes", "Fe Pública", "Se sanciona la reproducción apócrifa de marcas registradas y patentes comerciales para engañar al público sobre el origen de productos."),
        242 to ArticleMeta("Falsificación de Llaves y Tarjetas de Acceso", "Fe Pública", "A quien fabrique llaves maestras, ganzúas o tarjetas de clonación electrónica para penetrar en recintos protegidos se le aplicarán de uno a cinco años."),
        243 to ArticleMeta("Falsificación de Documentos Públicos y Privados", "Fe Pública", "Tratándose de documentos públicos se castigará con prisión de cuatro a ocho años; tratándose de documentos privados se sancionará con prisión de seis meses a cinco años."),
        244 to ArticleMeta("Modalidades Materiales de Falsedad Documental", "Fe Pública", "Se comete falsedad: estampando firma falsa; alterando fechas; atribuyendo a personas declaraciones que no hicieron; o intercalando cláusulas ficticias."),
        245 to ArticleMeta("Uso de Documento Falso con Conocimiento", "Fe Pública", "Para que la falsificación sea punible se requiere que el autor se proponga sacar algún provecho o causar perjuicio; quien use el documento a sabiendas sufrirá igual pena."),
        246 to ArticleMeta("Equiparación a Documento Público en Falsificación", "Fe Pública", "Se equiparan a documentos públicos: los títulos de crédito, letras de cambio, acciones, testamentos notariales y actas del registro civil."),
        247 to ArticleMeta("Falsedad en Declaraciones Judiciales y Peritajes", "Fe Pública", "Se impondrá de cuatro a ocho años de prisión a quien al declarar ante autoridad judicial o ministerial bajo protesta de decir verdad afirme una falsedad o niegue la verdad."),
        248 to ArticleMeta("Falsedad ante Autoridad Distinta de la Judicial", "Fe Pública", "A quien declare con falsedad ante autoridades administrativas o en trámites de pasaporte se le impondrán de dos a seis años de prisión."),
        249 to ArticleMeta("Variación Dolosa de Nombre o Domicilio", "Fe Pública", "Se sanciona a quien ante autoridades judiciales oculte o varíe su verdadero nombre, estado civil o domicilio para evadir la acción de la justicia."),
        250 to ArticleMeta("Usurpación de Funciones Públicas o Profesión", "Fe Pública", "Se sanciona con uno a seis años a quien se atribuya el carácter de servidor público sin serlo, o ejerza una profesión que requiera título sin tener cédula registrada."),
        251 to ArticleMeta("Uso Indebido de Insignias y Condecoraciones Civiles", "Fe Pública", "A quien use públicamente títulos de nobleza, órdenes de caballería o condecoraciones no reconocidas oficialmente se le aplicará sanción económica."),
        252 to ArticleMeta("Falsificación de Tarjetas de Crédito y Débito", "Fe Pública", "Se castigará con tres a nueve años de prisión a quien clone, falsifique o posea bandas magnéticas de tarjetas bancarias para efectuar disposiciones ilegales."),
        253 to ArticleMeta("Delitos contra el Abasto y Consumo Nacional", "Economía Pública", "Se sanciona a quienes acaparen artículos de primera necesidad o materias primas esenciales con el objeto de provocar el alza abusiva de precios en el mercado."),
        254 to ArticleMeta("Prácticas Monopólicas Ilícitas Federales", "Economía Pública", "A quienes concierten convenios para fijar precios monopólicos o limitar la producción y distribución en perjuicio de los consumidores (3 a 10 años)."),
        255 to ArticleMeta("Venta Ilícita de Medicamentos del Sector Salud", "Economía Pública", "Se sanciona a quien venda o comercialice al público medicamentos de propiedad exclusiva del IMSS, ISSSTE o Secretaría de Salud rotulados de distribución gratuita."),
        256 to ArticleMeta("Especulación Ilícita en Granos Básicos", "Economía Pública", "Se castiga a los intermediarios comerciales que retengan maíz, frijol o trigo para generar escasez ficticia y especular financieramente."),
        257 to ArticleMeta("Adulteración de Pesas y Medidas Comerciales", "Economía Pública", "A los comerciantes que alteren básculas, bombas despachadoras o medidores para entregar menor cantidad de producto se les aplicará prisión de uno a cinco años."),
        258 to ArticleMeta("Fraude en Concesiones y Servicios Federales", "Economía Pública", "Se sanciona a los concesionarios que cobren tarifas superiores a las autorizadas por la Secretaría de Infraestructura, Comunicaciones y Transportes."),
        259 to ArticleMeta("Exportación Clandestina de Alimentos Subsidiados", "Economía Pública", "Quien exporte ilegalmente mercancías subsidiadas por el Estado para el abasto popular sufrirá decomiso y penas de tres a ocho años de prisión."),
        260 to ArticleMeta("Tipo Penal de Abuso Sexual", "Libertad Sexual", "Comete abuso sexual quien ejecute en una persona sin su consentimiento, o la obligue a ejecutar para sí o en otra persona, actos sexuales sin llegar a la cópula (1 a 6 años)."),
        261 to ArticleMeta("Abuso Sexual en Menores de Quince Años", "Libertad Sexual", "Si el abuso sexual se comete contra persona menor de quince años o persona que no tenga capacidad de comprender, la pena será de seis a trece años de prisión."),
        262 to ArticleMeta("Tipo Penal de Estupro", "Libertad Sexual", "Al que tenga cópula con persona mayor de quince y menor de dieciocho años obteniendo su consentimiento mediante seducción o engaño se le impondrán de uno a cuatro años."),
        263 to ArticleMeta("Hostigamiento Sexual y Acoso Laboral", "Libertad Sexual", "Comete hostigamiento sexual quien con fines lascivos asedie a otra persona valiéndose de su posición jerárquica derivada de relaciones laborales, docentes o domésticas."),
        264 to ArticleMeta("Acoso Sexual en Espacios Públicos o Digitales", "Libertad Sexual", "Se sanciona el asedio o solicitud de favores sexuales reiterada en espacios públicos o medios electrónicos que cause intimidación o menoscabo a la víctima."),
        265 to ArticleMeta("Tipo Penal de Violación por Fuerza o Coacción", "Libertad Sexual", "Comete el delito de violación quien por medio de la violencia física o moral realice cópula con persona de cualquier sexo. Se sancionará con ocho a veinte años de prisión."),
        266 to ArticleMeta("Violación Equiparada e Incapacidad de Resistencia", "Libertad Sexual", "Se equipara a la violación y se castiga con igual pena cuando se realice cópula con persona privada de razón o sentido, o que por enfermedad no pueda resistir."),
        267 to ArticleMeta("Agravantes del Delito de Violación", "Libertad Sexual", "La pena de prisión se aumentará hasta en una mitad si la violación la comete un ascendiente, tutor, servidor público o si intervienen dos o más agresores."),
        268 to ArticleMeta("Violación Comodada por Narcóticos o Fármacos", "Libertad Sexual", "Se sanciona con las penas máximas a quien suministre somníferos o sustancias químicas a la víctima para anular su voluntad y cometer agresión sexual."),
        269 to ArticleMeta("Pérdida de Derechos Hereditarios por Violación", "Libertad Sexual", "El sentenciado por violación perderá la patria potestad sobre sus hijos y todo derecho sucesorio respecto de la víctima."),
        270 to ArticleMeta("Tratamiento Psicológico a Agresores Sexuales", "Libertad Sexual", "Las condenas por delitos contra la libertad sexual impondrán forzosamente tratamiento psicológico especializado de reinserción social."),
        271 to ArticleMeta("Pornografía Infantil y Explotación Sexual de Menores", "Libertad Sexual", "Se impondrá de siete a doce años de prisión a quien filme, fotografíe, almacene o comercialice material pornográfico en que intervengan menores de dieciocho años."),
        272 to ArticleMeta("Turismo Sexual Infantil en el Fuero Federal", "Libertad Sexual", "A quien promueva, gestione o facilite viajes con el propósito de tener relaciones sexuales con menores de edad se le aplicarán de diez a dieciocho años."),
        273 to ArticleMeta("Corrupción de Menores e Inducción al Delito", "Libertad Sexual", "Comete delito quien induzca a un menor al consumo habitual de bebidas alcohólicas, drogas o a la práctica de la mendicidad o prostitución."),
        274 to ArticleMeta("Lenocinio y Explotación de la Prostitución Ajena", "Libertad Sexual", "Comete lenocinio quien explote el comercio carnal de otra persona o mantenga casas de prostitución obteniendo un lucro económico de ello."),
        275 to ArticleMeta("Trata de Personas con Fines Sexuales", "Libertad Sexual", "La trata de personas para prostitución o servidumbre sexual se perseguirá conforme a la ley general especial con penas de hasta treinta años."),
        276 to ArticleMeta("Reparación del Daño Psicológico a Víctimas Sexuales", "Libertad Sexual", "La condena incluirá la cobertura de los gastos de tratamiento psicológico y psiquiátrico de la víctima por todo el tiempo que requiera su rehabilitación."),
        277 to ArticleMeta("Delito de Bigamia y Matrimonio Múltiple", "Estado Civil", "Se impondrá de uno a cinco años de prisión a quien estando válidamente unido en matrimonio contraiga otro con las formalidades legales sin estar disuelto el anterior."),
        278 to ArticleMeta("Sanción al Cónyuge Soltero Cómplice de Bigamia", "Estado Civil", "A la persona soltera que contraiga matrimonio con una casada a sabiendas de que subsiste el matrimonio previo de ésta se le aplicará igual sanción."),
        279 to ArticleMeta("Matrimonios Ilegales ante Oficiales Civiles", "Estado Civil", "Comete delito el juez o funcionario del registro civil que celebre matrimonio teniendo conocimiento de impedimentos legales no dispensados."),
        280 to ArticleMeta("Usurpación del Estado Civil de Otra Persona", "Estado Civil", "A quien se atribuya el estado civil de otra persona para gozar de derechos hereditarios o de filiación que no le corresponden se le impondrán de dos a seis años."),
        281 to ArticleMeta("Ocultación o Suposición de Partos", "Estado Civil", "Se sanciona a la mujer que finja un embarazo o parto para atribuir a un recién nacido derechos de estado civil que legalmente no le corresponden."),
        282 to ArticleMeta("Sustitución Fraudulenta de Recién Nacidos", "Estado Civil", "A quien sustituya a un niño por otro en hospitales o clínicas de maternidad se le impondrá pena privativa de libertad de cuatro a diez años de prisión."),
        283 to ArticleMeta("Inscripción Falsa en el Registro Civil", "Estado Civil", "A quien declare falsamente ante el juez del registro civil el fallecimiento o nacimiento de una persona se le sancionará con dos a seis años de prisión."),
        284 to ArticleMeta("Alteración y Falsedad en Actas de Defunción", "Estado Civil", "Los médicos que expidan certificados de defunción falsos para ocultar homicidios incurrirán en penas de prisión de cuatro a ocho años."),
        285 to ArticleMeta("Retención Indebida de Menores por Familiares", "Estado Civil", "A quien teniendo parentesco sustraiga a un menor de la custodia legítima conferida judicialmente se le impondrá prisión de uno a cuatro años."),
        286 to ArticleMeta("Sustracción Internacional de Menores de Edad", "Estado Civil", "Se castigará con cinco a diez años de prisión al progenitor que traslade o retenga ilícitamente a un menor fuera de la República Mexicana."),
        287 to ArticleMeta("Violencia Familiar en el Fuero Federal", "Familia", "Comete violencia familiar quien ejerza maltrato físico, verbal, psicológico o económico contra persona con quien tenga relación conyugal o de parentesco."),
        288 to ArticleMeta("Concepto Dogmático de Lesiones Corporales", "Vida e Integridad", "Bajo el nombre de lesión se comprende no solamente las heridas, escoriaciones y contusiones, sino toda alteración en la salud producida por causa externa imputable."),
        289 to ArticleMeta("Lesiones Leves que Sanan en Menos de Quince Días", "Vida e Integridad", "Al que infiera una lesión que no ponga en peligro la vida y tarde en sanar menos de quince días se le impondrán de tres a ocho meses de prisión o multa."),
        290 to ArticleMeta("Lesiones que Sanan en Más de Quince Días", "Vida e Integridad", "Al que cause una lesión que no ponga en peligro la vida pero tarde en sanar más de quince días se le impondrá de cuatro meses a dos años de prisión."),
        291 to ArticleMeta("Lesiones con Deformidad Facial Perpetua", "Vida e Integridad", "Se impondrá de dos a cinco años de prisión al que infiera una lesión que deje al ofendido cicatriz en la cara perpetuamente notable."),
        292 to ArticleMeta("Lesiones con Pérdida de Órgano o Función", "Vida e Integridad", "Se impondrá de cinco a ocho años de prisión al que cause una lesión de la que resulte pérdida de un miembro, de un ojo o deformidad incorregible."),
        293 to ArticleMeta("Lesiones Gravísimas con Parálisis o Pérdida Mental", "Vida e Integridad", "Al que infiera una lesión que produzca pérdida de la vista en ambos ojos, incapacidad permanente para trabajar o enajenación mental (6 a 10 años)."),
        294 to ArticleMeta("Lesiones que Ponen en Peligro la Vida", "Vida e Integridad", "Al que infiera una lesión que por su naturaleza ponga en peligro la vida humana se le impondrá de tres a seis años de prisión."),
        295 to ArticleMeta("Lesiones en Riña o Duelo", "Vida e Integridad", "Al que hiera o lesione en riña se le impondrá la mitad o cinco sextos de la pena según sea el provocado o el provocador de la contienda."),
        296 to ArticleMeta("Lesiones Calificadas con Alevosía o Ventaja", "Vida e Integridad", "Cuando las lesiones se cometan con premeditación, alevosía, ventaja o traición, la pena aplicable se aumentará hasta en dos tercios de la condena."),
        297 to ArticleMeta("Agravación de Lesiones contra Ascendientes", "Vida e Integridad", "Si las lesiones son inferidas a un ascendiente consanguíneo, descendiente o cónyuge, la pena de prisión se aumentará de dos a cinco años más."),
        298 to ArticleMeta("Lesiones con Ataques de Ácido o Sustancias Químicas", "Vida e Integridad", "Se impondrá de siete a quince años de prisión a quien arroje ácido o sustancias corrosivas causando quemaduras destructivas en el cuerpo de la víctima."),
        299 to ArticleMeta("Lesiones Cometidas por Conductores Ebrios", "Vida e Integridad", "Las lesiones culposas producidas por tránsito de vehículos se sancionarán con penas privativas agravadas si el conductor se halla en estado de ebriedad."),
        300 to ArticleMeta("Persecución por Querella en Lesiones Leves", "Vida e Integridad", "Las lesiones simples que no pongan en peligro la vida y tarden en sanar menos de quince días sólo se perseguirán por querella de la parte ofendida."),
        301 to ArticleMeta("Obligación de Reparar Gastos Médicos", "Vida e Integridad", "En todos los delitos de lesiones se condenará forzosamente al responsable al pago íntegro de los gastos de hospitalización, cirugías y prótesis."),
        302 to ArticleMeta("Tipo Penal de Homicidio: Privación de la Vida", "Vida e Integridad", "Comete el delito de homicidio el que priva de la vida a otro ser humano."),
        303 to ArticleMeta("Requisitos para Declarar la Muerte por Homicidio", "Vida e Integridad", "Para la aplicación de las sanciones se requiere que la muerte se deba a las alteraciones causadas por la lesión en el cadáver y que ésta se verifique en 60 días."),
        304 to ArticleMeta("Mortalidad de la Lesión por Peritaje Médico", "Vida e Integridad", "Siempre se tendrá como mortal una lesión cuando la muerte se verifique por efecto de la lesión misma o de sus consecuencias inmediatas comprobadas por autopsia."),
        305 to ArticleMeta("Causas Extrañas que no Excluyen el Homicidio", "Vida e Integridad", "No eximirá de la pena de homicidio la circunstancia de que el ofendido tuviese una enfermedad preexistente si la lesión aceleró fatalmente la muerte."),
        306 to ArticleMeta("Concurso de Asistencias Médicas en el Desenlace", "Vida e Integridad", "Tampoco eximirá al autor de la lesión si la muerte se produce aun habiéndose suministrado los auxilios médicos oportunos y adecuados."),
        307 to ArticleMeta("Sanciones al Homicidio Simple Intencional", "Vida e Integridad", "Al responsable de cualquier homicidio simple intencional que no tenga señalada una pena especial en este Código se le impondrán de doce a veinticuatro años de prisión."),
        308 to ArticleMeta("Homicidio Cometido en Riña o Duelo", "Vida e Integridad", "Al que prive de la vida a otro en riña se le impondrán de cuatro a doce años de prisión si es el provocador, o de tres a siete años si es el provocado."),
        309 to ArticleMeta("Definición Legal de Riña para Efectos Penales", "Vida e Integridad", "Por riña se entiende la contienda de obra y no de palabra entre dos o más personas que se agreden recíprocamente."),
        310 to ArticleMeta("Homicidio y Lesiones por Emoción Violenta", "Vida e Integridad", "Al que mate a su cónyuge o a otra persona hallándola en flagrante acto carnal se le aplicará pena atenuada si actuó en estado de emoción violenta irreprimible."),
        311 to ArticleMeta("Inadmisibilidad de Atenuante por Crimen de Odio", "Vida e Integridad", "En ningún caso podrá invocarse la emoción violenta cuando el homicidio se cometa por razones de odio, género, orientación sexual o violencia familiar previa."),
        312 to ArticleMeta("Tipo Penal de Instigación o Ayuda al Suicidio", "Vida e Integridad", "El que preste auxilio o induzca a otro para que se suicide será castigado con la pena de uno a cinco años de prisión; si se consuma la muerte, de tres a ocho años."),
        313 to ArticleMeta("Homicidio por Piedad o Eutanasia no Autorizada", "Vida e Integridad", "A quien por móviles de piedad y ante peticiones insistentes de un enfermo desahuciado le cause la muerte se le atenuará la pena de dos a cinco años."),
        314 to ArticleMeta("Homicidio en Razón de Parentesco", "Vida e Integridad", "A quien prive de la vida a su ascendiente o descendiente consanguíneo en línea recta, sabiendo el delincuente ese parentesco, se le impondrán de 30 a 60 años de prisión."),
        315 to ArticleMeta("Circunstancias Calificativas del Homicidio", "Vida e Integridad", "Se entiende que el homicidio y las lesiones son calificados cuando se cometan con premeditación, con ventaja, con alevosía o a traición."),
        316 to ArticleMeta("Supuestos de Ventaja en el Homicidio Calificado", "Vida e Integridad", "Se considera ventaja: cuando el delincuente es superior en fuerza física; cuando emplea armas; o cuando el sujeto pasivo se halla inerme o caído."),
        317 to ArticleMeta("Alevosía en Ataques Sorpresivos a Traición", "Vida e Integridad", "La alevosía consiste en no dar oportunidad al agredido de prevenir el ataque o defenderse de improviso."),
        318 to ArticleMeta("Premeditación por Reflexión Fría del Crimen", "Vida e Integridad", "Hay premeditación cuando el sujeto concibe el hecho criminal con antelación, reflexiona sobre sus medios y persigue su consumación con serenidad de ánimo."),
        319 to ArticleMeta("Homicidio Calificado Cometido por Retribución o Precio", "Vida e Integridad", "Se aumentará la pena de prisión hasta sesenta años cuando el homicidio se cometa mediante pago, recompensa o promesa remuneratoria (sicariato)."),
        320 to ArticleMeta("Sanciones al Homicidio Calificado", "Vida e Integridad", "Al responsable de homicidio calificado se le impondrán de treinta a sesenta años de prisión sin derecho a sustitución de condena ni beneficios."),
        321 to ArticleMeta("Homicidio Calificado Cometido contra Menores", "Vida e Integridad", "Si la víctima del homicidio calificado fuere menor de doce años o persona con discapacidad, se impondrán las penas máximas de sesenta años."),
        322 to ArticleMeta("Homicidio Calificado Cometido contra Policías", "Vida e Integridad", "Al que prive de la vida a un elemento de las fuerzas de seguridad pública en ejercicio de sus funciones se le impondrán de cuarenta a sesenta años de prisión."),
        323 to ArticleMeta("Homicidio Culposo por Tránsito de Vehículos", "Vida e Integridad", "El homicidio cometido culposamente con motivo del tránsito de vehículos se sancionará con cuatro a diez años de prisión si el conductor iba intoxicado."),
        324 to ArticleMeta("Pensión para Dependientes de la Víctima de Homicidio", "Vida e Integridad", "La reparación del daño por homicidio comprenderá una pensión económica mensual de alimentos para los hijos menores del occiso hasta la mayoría de edad."),
        325 to ArticleMeta("Tipo Penal de Feminicidio por Razones de Género", "Vida e Integridad", "Comete feminicidio quien prive de la vida a una mujer por razones de género. Sanción de cuarenta a sesenta años de prisión y quinientos a mil días multa."),
        326 to ArticleMeta("Circunstancias Determinantes de Género en Feminicidio", "Vida e Integridad", "Se consideran razones de género: signos de violencia sexual; lesiones infamantes o mutilaciones; antecedentes de violencia familiar; amenazas previas o cuerpo expuesto públicamente."),
        327 to ArticleMeta("Sanción a Servidores por Obstrucción en Feminicidio", "Vida e Integridad", "Al servidor público que retarde o entorpezca maliciosamente la investigación de un feminicidio se le impondrán de tres a ocho años de prisión y destitución."),
        328 to ArticleMeta("Pérdida de la Patria Potestad del Sujeto Activo", "Vida e Integridad", "El sentenciado por feminicidio perderá definitivamente todo derecho respecto a los hijos nacidos de la unión con la víctima, pasando la tutela a los abuelos maternos."),
        329 to ArticleMeta("Tipo Penal de Aborto y Concepto Legal", "Vida e Integridad", "Aborto es la interrupción del embarazo en cualquier momento de la preñez después de las semanas fijadas por la normatividad constitucional vigente."),
        330 to ArticleMeta("Aborto Forzado Cometido sin Consentimiento", "Vida e Integridad", "Al que haga abortar a una mujer sin su consentimiento expreso se le impondrán de cinco a ocho años de prisión; con violencia física de ocho a diez años."),
        331 to ArticleMeta("Sanciones a Profesionales por Aborto Forzado", "Vida e Integridad", "Si el aborto forzado lo causa un médico o partero, además de las sanciones de prisión se le suspenderá de dos a cinco años en el ejercicio profesional."),
        332 to ArticleMeta("Excluyentes de Responsabilidad en el Aborto", "Vida e Integridad", "No es punible el aborto cuando el embarazo sea resultado de una violación, cuando la mujer corra peligro de muerte o por conducta culposa involuntaria."),
        333 to ArticleMeta("Aborto por Peligro de Muerte de la Mujer Gestante", "Vida e Integridad", "No se aplicará pena cuando de no provocarse el aborto la mujer embarazada corra grave peligro de muerte a juicio del médico que la asista."),
        334 to ArticleMeta("Consentimiento Informado de la Mujer", "Vida e Integridad", "En los casos de aborto no punible bastará la solicitud informada de la mujer y la denuncia previa tratándose del delito de violación."),
        335 to ArticleMeta("Tipo Penal de Abandono de Personas Desvalidas", "Vida e Integridad", "Al que abandone a un niño incapaz de cuidarse a sí mismo o a una persona enferma teniendo obligación de cuidarla se le impondrán de un mes a cuatro años."),
        336 to ArticleMeta("Incumplimiento de Obligaciones de Asistencia Familiar", "Familia", "Al que sin motivo justificado incumpla con la obligación de dar alimentos a sus hijos o cónyuge se le impondrá de seis meses a cinco años de prisión y pago de adeudos."),
        337 to ArticleMeta("Reparación Económica de Pensiones Insolutas", "Familia", "El deudor alimentario no podrá ser absuelto ni obtener libertad condicional en tanto no cubra o garantice la totalidad de las pensiones alimenticias caídas."),
        338 to ArticleMeta("Pérdida de Derechos Hereditarios por Abandono", "Familia", "El que incurra en abandono de hijos o cónyuge perderá la patria potestad y los derechos a heredar al ofendido."),
        339 to ArticleMeta("Abandono de Atropellados por Conductores", "Vida e Integridad", "Al que lesione culposamente y no auxilie a la víctima dejándola abandonada se le impondrán de uno a cinco años de prisión adicionales al delito base."),
        340 to ArticleMeta("Negativa de Atención Médica de Urgencia en Hospitales", "Salud Pública", "A los médicos o encargados de clínicas que nieguen atención de urgencia a una persona en peligro de muerte se les aplicará de uno a cuatro años de prisión."),
        341 to ArticleMeta("Omisión de Socorro a Persona Desamparada", "Vida e Integridad", "Al que encuentre a una persona perdida o desamparada en peligro manifiesto y no le preste socorro pudiendo hacerlo sin riesgo propio se le impondrá multa."),
        342 to ArticleMeta("Abandono de Personas de la Tercera Edad", "Familia", "A quien abandone a un adulto mayor con discapacidad física o motriz teniendo el deber de asistirlo se le aumentará la pena hasta en una mitad."),
        343 to ArticleMeta("Medidas Tutelares de Alimentos Provisionales", "Familia", "El juez penal dictará de oficio embargo precautorio sobre el salario y cuentas del deudor para garantizar la pensión alimenticia de los acreedores."),
        344 to ArticleMeta("Tipo Penal de Privación Ilegal de la Libertad", "Libertad Personal", "Al particular que prive a otro de su libertad personal sin derecho ni orden de autoridad competente se le impondrá de seis meses a tres años de prisión."),
        345 to ArticleMeta("Privación de la Libertad Agravada por Retención", "Libertad Personal", "Si la privación de la libertad excede de veinticuatro horas o se realiza con violencia física, la pena de prisión aumentará de dos a seis años."),
        346 to ArticleMeta("Retención Ilegal en Centros de Rehabilitación", "Libertad Personal", "A los encargados de anexos o clínicas de rehabilitación que mantengan recluidas a personas contra su voluntad sin orden legal se les castigará con prisión."),
        347 to ArticleMeta("Detención Arbitraria por Particulares", "Libertad Personal", "El particular que retenga a una persona aprehendida fuera de los supuestos estrictos de flagrancia incurrirá en delito de detención ilegal."),
        348 to ArticleMeta("Tipo Penal de Secuestro y Remisión a Ley Especial", "Libertad Personal", "El delito de secuestro en todas sus modalidades y agravantes se sancionará conforme a la Ley General para Prevenir y Sancionar los Delitos en Materia de Secuestro."),
        349 to ArticleMeta("Secuestro Simulado y Autoextorsión", "Libertad Personal", "A quien simule estar secuestrado o coopere en su propio secuestro para obtener rescate de sus familiares se le impondrán de dos a ocho años de prisión."),
        350 to ArticleMeta("Penas Aplicables a Colaboradores de Secuestro", "Libertad Personal", "A quien proporcione información, casas de seguridad o celulares a bandas de secuestradores se le impondrán de veinte a cuarenta años de prisión."),
        351 to ArticleMeta("Tipo Penal de Rapto de Personas", "Libertad Personal", "Al que por medio de la violencia física o moral sustraiga a una persona para satisfacer deseos eróticos o contraer matrimonio se le impondrán de uno a cinco años."),
        352 to ArticleMeta("Persecución por Querella en Rapto", "Libertad Personal", "El rapto sólo se perseguirá por querella de la víctima agraviada o de sus padres si fuere menor de edad."),
        353 to ArticleMeta("Extinción de Pena por Matrimonio Inadmisible", "Libertad Personal", "El posterior matrimonio con la persona raptada en ningún caso extinguirá la acción penal por ser una figura superada en el orden garantista."),
        354 to ArticleMeta("Violación Cometida en Rapto", "Libertad Personal", "Si con motivo del rapto se comete violación, se acumularán forzosamente las penas de ambos delitos con las máximas calificativas."),
        355 to ArticleMeta("Trata de Personas con Fines Laborales o Servidumbre", "Libertad Personal", "Se impondrá de diez a veinte años de prisión a quien capte, traslade o retenga a personas para someterlas a trabajos forzados o esclavitud."),
        356 to ArticleMeta("Explotación Laboral Indígena y Jornalera", "Libertad Personal", "A quien aproveche la marginación de comunidades indígenas para imponer jornadas inhumanas sin salario digno se le aplicará pena privativa federal."),
        357 to ArticleMeta("Mendicidad Forzada de Menores de Edad", "Libertad Personal", "A quien obligue a niños o ancianos a pedir limosna en calles y avenidas reteniendo las dádivas obtenidas se le impondrán de cuatro a nueve años."),
        358 to ArticleMeta("Servidumbre por Deudas y Esclavitud Encubierta", "Libertad Personal", "Se prohíbe y sanciona con diez a quince años de prisión la retención de personas o entrega de hijos bajo pretexto de saldar deudas económicas de los padres."),
        359 to ArticleMeta("Retención de Documentos Migratorios a Trabajadores", "Libertad Personal", "A los empleadores que retengan pasaportes o visas a trabajadores extranjeros para forzarlos a laborar se les aplicarán de tres a ocho años."),
        360 to ArticleMeta("Protección Integral a Víctimas de Trata", "Libertad Personal", "Las víctimas de trata gozarán de resguardo institucional en albergues seguros, atención médica gratuita y regularización de estancia migratoria."),
        361 to ArticleMeta("Decomiso de Bienes Inmuebles Usados para Trata", "Libertad Personal", "Los hoteles, predios o vehículos utilizados para la trata de personas o secuestro causarán extinción de dominio en favor del Estado."),
        362 to ArticleMeta("Tipo Penal de Ataques a la Paz Pública", "Paz Pública", "Al que mediante violencia en las cosas o personas realice actos contra la paz pública perturbando el orden se le impondrán de dos a siete años."),
        363 to ArticleMeta("Destrucción de Inmuebles Públicos Federales", "Paz Pública", "A quien incendie o cause destrozos en sedes de los Poderes de la Unión o monumentos públicos se le aplicará pena privativa de cinco a diez años."),
        364 to ArticleMeta("Detención Ilegal de Servidores Públicos por Rebeldes", "Libertad Personal", "A quien secuestre a funcionarios federales para presionar al gobierno en la toma de decisiones se le aplicarán de veinte a cuarenta años."),
        365 to ArticleMeta("Tipo Penal de Coacción Ilícita entre Particulares", "Libertad Personal", "Al que con violencia obligue a otro a hacer lo que no quiere o le impida hacer lo que la ley no prohíbe se le impondrán de seis meses a dos años."),
        366 to ArticleMeta("Modalidades de Secuestro Extorsivo Agravado", "Libertad Personal", "Penalidades de cuarenta a ochenta años de prisión cuando en el secuestro se mutile a la víctima o sea cometida por policías o expolicías."),
        367 to ArticleMeta("Tipo Penal de Robo: Apoderamiento Ilegítimo", "Patrimonio", "Comete el delito de robo: el que se apodera de una cosa mueble ajena, sin derecho y sin consentimiento de la persona que puede disponer de ella con arreglo a la ley."),
        368 to ArticleMeta("Equiparación al Delito de Robo", "Patrimonio", "Se equipara al robo: el apoderamiento o destrucción de cosa propia que se halle legalmente en poder de otro; y el uso indebido de energía eléctrica o fluidos."),
        369 to ArticleMeta("Consumación del Delito de Robo", "Patrimonio", "Para la graduación de la pena se tendrá en cuenta el valor de lo robado en el momento de la consumación del apoderamiento, aun cuando el autor lo abandone."),
        370 to ArticleMeta("Escalas Punitivas del Robo tasadas en Salarios / UMA", "Patrimonio", "Sanción de hasta dos años si el monto no excede de 100 veces la UMA; de dos a cuatro años de 100 a 500 veces; y de cuatro a diez años si excede de 500 veces."),
        371 to ArticleMeta("Robo Cometido sin Violencia Física", "Patrimonio", "En el robo simple sin violencia se aplicarán las penas de la escala patrimonial básica con posibilidad de salida alterna si se repara el daño integralmente."),
        372 to ArticleMeta("Robo con Violencia Física o Moral", "Patrimonio", "Si el robo se ejecuta con violencia en las personas, se aumentará la pena de tres a ocho años de prisión sobre la sanción que corresponda por el valor de lo robado."),
        373 to ArticleMeta("Concepto de Violencia en las Personas en Robo", "Patrimonio", "La violencia en el robo puede ser física (fuerza material sobre la persona) o moral (amenazas de males graves inminentes a la persona o su familia)."),
        374 to ArticleMeta("Robo en Paraje Solitario o de Noche", "Patrimonio", "Se agravará la pena de robo cuando se cometa aprovechando la oscuridad de la noche, en caminos despoblados o con superioridad numérica de agresores."),
        375 to ArticleMeta("Robo Calificado en Lugar Cerrado o Casa Habitación", "Patrimonio", "Se impondrá de dos a siete años más de prisión cuando el robo se cometa en casa habitación, aposento o dependencias con fractura de cerraduras o escalamiento."),
        376 to ArticleMeta("Robo Calificado a Vehículos Automotores", "Patrimonio", "El robo de vehículos automotores terrestres o de autopartes se sancionará con pena de siete a quince años de prisión sin derecho a libertad condicional."),
        377 to ArticleMeta("Desmantelamiento Clandestino de Vehículos Robados", "Patrimonio", "A quien posea, desmantele, altere números de serie o comercialice autopartes de vehículos robados se le aplicarán de cinco a doce años de prisión."),
        378 to ArticleMeta("Robo a Instituciones Financieras y Bancarias", "Patrimonio", "El robo cometido en sucursales bancarias, cajeros automáticos o contra vehículos de transporte de valores se sancionará con diez a dieciocho años de prisión."),
        379 to ArticleMeta("Excluyente de Responsabilidad por Robo Famelico", "Patrimonio", "No se castigará al que sin emplear engaño ni violencia se apodere de los alimentos estrictamente indispensables para satisfacer sus necesidades personales o familiares inmediatas."),
        380 to ArticleMeta("Robo entre Parientes y Persecución por Querella", "Patrimonio", "El robo cometido entre cónyuges, ascendientes o descendientes sólo se perseguirá por querella y no se aplicará pena privativa si se restituye lo robado."),
        381 to ArticleMeta("Catálogo de Circunstancias Agravantes del Robo", "Patrimonio", "Fracciones que sancionan el robo cometido por dependientes domésticos, huéspedes, dependientes comerciales o con empleo de armas de fuego."),
        382 to ArticleMeta("Tipo Penal de Abuso de Confianza", "Patrimonio", "Al que con perjuicio de alguien disponga para sí o para otro de una cosa ajena mueble de la que se le haya transmitido la tenencia y no el dominio (multa y prisión)."),
        383 to ArticleMeta("Equiparación al Abuso de Confianza", "Patrimonio", "Se equipara al abuso de confianza: la retención indebida de una cosa empeñada; y la negativa del depositario judicial a devolver los bienes embargados."),
        384 to ArticleMeta("Sanción al Depositario Infiel de Bienes Embargados", "Patrimonio", "El depositario nombrado en juicio que disponga de los bienes o no los ponga a disposición del juez dentro de tres días será castigado con penas de abuso de confianza."),
        385 to ArticleMeta("Abuso de Confianza entre Socios Comerciales", "Patrimonio", "A quien siendo socio o administrador de una sociedad mercantil disponga de fondos comunes en beneficio privado se le impondrán de dos a ocho años de prisión."),
        386 to ArticleMeta("Tipo Penal de Fraude Genérico", "Patrimonio", "Comete el delito de fraude el que engañando a uno o aprovechándose del error en que éste se halla se hace ilícitamente de alguna cosa o alcanza un lucro indebido."),
        387 to ArticleMeta("Catálogo Taxativo de Fraudes Específicos", "Patrimonio", "Fracciones I a XXI: fraude por venta de cosa ajena; libramiento de cheques sin fondos; simulación de contratos; fraude de usura; y sorteos ficticios."),
        388 to ArticleMeta("Fraude Cometido por Administradores de Bienes", "Patrimonio", "Al que por cualquier motivo tenga a su cargo la administración de bienes ajenos y perjudique a su titular alterando cuentas o inflando gastos dolosamente."),
        389 to ArticleMeta("Fraude en Promesas de Empleo o Visas Extranjeras", "Patrimonio", "A quien prometa puestos de trabajo en el gobierno o visas de trabajo en el extranjero exigiendo cantidades de dinero sin tener facultades legales."),
        390 to ArticleMeta("Tipo Penal de Extorsión y Coacción Patrimonial", "Patrimonio", "Al que sin derecho obligue a otro a dar, hacer, dejar de hacer o tolerar algo, obteniendo un lucro para sí o para otro o causando a alguien un perjuicio patrimonial (2 a 8 años)."),
        391 to ArticleMeta("Cobro de Piso y Amenazas del Crimen Organizado", "Patrimonio", "Si la extorsión se comete por grupos delictivos exigiendo cobro de cuotas a comerciantes bajo amenaza armada, la pena será de ocho a quince años de prisión."),
        392 to ArticleMeta("Extorsión Telefónica y Fraude Cibernético", "Patrimonio", "Se sanciona a quien mediante llamadas o mensajes extorsivos simule tener secuestrado a un familiar para forzar depósitos bancarios urgentes."),
        393 to ArticleMeta("Extorsión Cometida por Policías o Exagentes", "Patrimonio", "Las penas de extorsión se aumentarán hasta en una mitad cuando el extorsionador sea o haya sido miembro de una corporación policial."),
        394 to ArticleMeta("Decomiso de Cuentas Usadas para Depósitos de Extorsión", "Patrimonio", "Las cuentas bancarias receptoras de depósitos derivados de extorsión serán inmediatamente inmovilizadas y decomisadas por la autoridad ministerial."),
        395 to ArticleMeta("Tipo Penal de Despojo de Inmuebles o Aguas", "Patrimonio", "Se impondrá de tres meses a cinco años de prisión al que de propia autoridad y haciendo uso de violencia o engaño o furtivamente ocupe un inmueble ajeno o turbe su posesión."),
        396 to ArticleMeta("Despojo Colectivo por Grupos Invasores", "Patrimonio", "Cuando el despojo se cometa por dos o más personas o por grupos organizados de invasores profesionales, la pena aumentará de dos a seis años de prisión."),
        397 to ArticleMeta("Tipo Penal de Daño en los Bienes por Incendio", "Patrimonio", "Se impondrá de cinco a diez años de prisión al que cause incendio, inundación o explosión causando daño en edificios públicos, refinerías o archivos federales."),
        398 to ArticleMeta("Daño en Propiedad Ajena Doloso", "Patrimonio", "Al que por cualquier medio destruya o deteriore una cosa ajena se le impondrán las penas de la escala del robo según el valor del daño material resentido."),
        399 to ArticleMeta("Persecución por Querella en Daños Culposos", "Patrimonio", "El delito de daño en los bienes culposo con motivo del tránsito de vehículos sólo se perseguirá por querella de parte si el conductor no iba ebrio."),
        400 to ArticleMeta("Tipo Penal de Encubrimiento por Receptación", "Encubrimiento", "Se impondrá de tres meses a tres años de prisión a quien después de consumado el delito adquiera, reciba u oculte el producto del mismo sabiendo esta circunstancia."),
        401 to ArticleMeta("Comercio Habitual de Objetos de Procedencia Ilícita", "Encubrimiento", "A los encargados de casas de empeño o deshuesaderos que adquieran habitualmente objetos robados sin verificar facturas se les aplicarán de tres a diez años."),
        402 to ArticleMeta("Encubrimiento entre Parientes y Exenciones", "Encubrimiento", "No se aplicará pena por encubrimiento de fuga a los ascendientes, descendientes, cónyuge o hermanos del delincuente por lazos de afecto y parentesco."),
        403 to ArticleMeta("Omisión de Denunciar Delitos Graves Conocidos", "Encubrimiento", "Los servidores públicos que en ejercicio de sus funciones tengan conocimiento de delitos federales graves y no los denuncien al MP sufrirán prisión e inhabilitación."),
        404 to ArticleMeta("Destrucción de Rastreos y Huellas del Crimen", "Encubrimiento", "A quien altere o limpie la escena del crimen o destruya cadáveres para impedir la investigación judicial se le impondrán de dos a seis años de prisión."),
        405 to ArticleMeta("Sanción a Abogados que Oculten Pruebas Relevantes", "Encubrimiento", "Los defensores que oculten armas homicidas u objetos del delito para beneficiar al imputado incurrirán en responsabilidad penal accesoria."),
        406 to ArticleMeta("Decomiso de Bienes Receptados Clandestinamente", "Encubrimiento", "Todos los objetos muebles robados recuperados en poder de receptadores serán devueltos inmediatamente a sus legítimos dueños sin costo alguno."),
        407 to ArticleMeta("Encubrimiento de Fugas Penitenciarias", "Encubrimiento", "A quien ayude a fugarse a un procesado o sentenciado de una cárcel federal se le impondrán de uno a cinco años; si es celador, de cuatro a diez años."),
        408 to ArticleMeta("Encubrimiento por Falsa Coartada Testimonial", "Encubrimiento", "A los testigos que declaren falsas coartadas para encubrir la presencia del delincuente en el lugar de los hechos se les aplicará pena privativa."),
        409 to ArticleMeta("Penalidad Gradual para Receptadores Primarios", "Encubrimiento", "Si el receptador devuelve espontáneamente el objeto antes de dictarse sentencia y colabora en la detención del autor principal, se le reducirá la pena a la mitad."),
        410 to ArticleMeta("Registro Obligatorio de Compradores de Metales", "Encubrimiento", "Los compradores de chatarra o cobre que adquieran cables de la CFE o tapas de alcantarilla sin acreditar procedencia lícita serán sancionados con decomiso."),
